lv_obj_t *g_wifi_scan_spinner = NULL;
void wifi_scan_spinner_set_visible(bool visible) {
    if (!g_wifi_scan_spinner || !lv_obj_is_valid(g_wifi_scan_spinner)) return;
    if (visible) lv_obj_clear_flag(g_wifi_scan_spinner, LV_OBJ_FLAG_HIDDEN);
    else lv_obj_add_flag(g_wifi_scan_spinner, LV_OBJ_FLAG_HIDDEN);
}

