extern bool is_company_name_keyboard(lv_obj_t *obj);

void keyboard_color_draw_task_cb(lv_event_t *e) {
    lv_obj_t *obj = lv_event_get_current_target(e);
    lv_draw_task_t *draw_task = (lv_draw_task_t *)lv_event_get_param(e);
    if (!draw_task || !draw_task->draw_dsc) return;
    if (((lv_draw_dsc_base_t *)draw_task->draw_dsc)->part != LV_PART_ITEMS) return;

    int32_t id = ((lv_draw_dsc_base_t *)draw_task->draw_dsc)->id1;
    const char *txt = lv_buttonmatrix_get_button_text(obj, id);
    if (!txt) return;

    bool is_pressed = (lv_buttonmatrix_get_selected_button(obj) == (uint32_t)id) && (lv_obj_get_state(obj) & LV_STATE_PRESSED);

    lv_draw_fill_dsc_t *fill_dsc = lv_draw_task_get_fill_dsc(draw_task);
    lv_draw_label_dsc_t *label_dsc = lv_draw_task_get_label_dsc(draw_task);

    bool is_bksp = (strcmp(txt, LV_SYMBOL_BACKSPACE) == 0 || strcmp(txt, "Del") == 0 || strcmp(txt, "پاک") == 0 || strcmp(txt, "پاک کردن") == 0 || strcmp(txt, "Sil") == 0);
    bool is_ok   = (strcmp(txt, LV_SYMBOL_OK) == 0 || strcmp(txt, "تایید") == 0 || strcmp(txt, "تأیید") == 0 || strcmp(txt, "Enter") == 0 || strcmp(txt, "Tamam") == 0 || strcmp(txt, "OK") == 0);

/* =========================================================================
 * 🔒 LOCKED KEYBOARD ICON VERTICAL OFFSETS (قفل قطعی و تخلف‌ناپذیر آفست کیبوردها)
 * هر کیبورد آفست عمودی مستقل خود را دارد و تغییر یک کیبورد نباید بقیه را جابجا کند:
 * 1. KB_Y_OFF_LINK_ENTRY   (-4): کیبورد ورود لینک (۵ پیکسل پایین‌تر طبق دستور کارفرما: -9 + 5 = -4)
 * 2. KB_Y_OFF_WIFI_PW      (-4): کیبورد رمز وای‌فای (۱۳ پیکسل بالاتر از +9 برای وسط‌چین عمودی در کلیدهای ۴۸px)
 * 3. KB_Y_OFF_COMPANY_NAME (+3): کیبورد نام شرکت (تایید شده روی برد با گپ ۱۱ بالا و ۱۳ پایین)
 * 4. KB_Y_OFF_DEFAULT_NUM  (+8): کیبوردهای عددی ادمین و تنظیم مقادیر
 * ========================================================================= */
#define KB_Y_OFF_LINK_ENTRY   (-4)
#define KB_Y_OFF_WIFI_PW      (-4)
#define KB_Y_OFF_COMPANY_NAME (3)
#define KB_Y_OFF_DEFAULT_NUM  (8)
#define KB_Y_OFF_FW_PASS      (0)

    bool is_wifi_pw = (objects.keybord && obj == objects.keybord);
    bool is_link_kb = (objects.link_entry_keyboard && obj == objects.link_entry_keyboard);
    bool is_company = is_company_name_keyboard(obj);
    bool is_fw_pass = (objects.frameware_password_keybord && obj == objects.frameware_password_keybord);

    int y_off = KB_Y_OFF_DEFAULT_NUM;
    if (is_link_kb) {
        y_off = KB_Y_OFF_LINK_ENTRY;   // 🔒 LOCKED: -4 (۵ پیکسل پایین‌تر طبق دستور کارفرما)
    } else if (is_wifi_pw) {
        y_off = KB_Y_OFF_WIFI_PW;      // 🔒 LOCKED: -4 (۱۳ پیکسل بالاتر برای وسط‌چین عمودی در کلیدهای ۴۸px)
    } else if (is_company) {
        y_off = KB_Y_OFF_COMPANY_NAME; // 🔒 LOCKED: 3 (تایید شده روی سخت‌افزار با گپ ۱۱ بالا و ۱۳ پایین)
    } else if (is_fw_pass) {
        y_off = KB_Y_OFF_FW_PASS;      // 🔒 LOCKED: 0 (۸ پیکسل بالاتر از ۸ پیش‌فرض جهت وسط‌چین دقیق آیکون‌های تایید و پاک‌کردن)
    }

    if (is_bksp) {
        if (fill_dsc) {
            fill_dsc->color = is_pressed ? lv_color_hex(0xffef4444) : lv_color_hex(0xffdc2626);
            fill_dsc->opa = LV_OPA_COVER;
            fill_dsc->radius = 6;
        }
        if (label_dsc) {
            label_dsc->color = lv_color_hex(0xffffffff);
            label_dsc->font = &lv_font_montserrat_28;
            draw_task->area.y1 += y_off;
            draw_task->area.y2 += y_off;
            draw_task->_real_area = draw_task->area;
        }
    } else if (is_ok) {
        if (fill_dsc) {
            fill_dsc->color = is_pressed ? lv_color_hex(0xff22c55e) : lv_color_hex(0xff16a34a);
            fill_dsc->opa = LV_OPA_COVER;
            fill_dsc->radius = 6;
        }
        if (label_dsc) {
            label_dsc->color = lv_color_hex(0xffffffff);
            label_dsc->font = &lv_font_montserrat_28;
            draw_task->area.y1 += y_off;
            draw_task->area.y2 += y_off;
            draw_task->_real_area = draw_task->area;
        }
    } else if (is_pressed) {
        if (fill_dsc) {
            fill_dsc->color = lv_color_hex(0xff0284c7);
            fill_dsc->opa = LV_OPA_COVER;
        }
        if (label_dsc) {
            label_dsc->color = lv_color_hex(0xffffffff);
        }
    }
}


