static int32_t get_ui_language_index();
static int32_t ui_lang_to_flow_index_local(int32_t lang) {
    if (lang == 2) return 1; // English
    if (lang == 3) return 2; // Turkish
    return 0;                // Persian
}
void apply_language_now(int32_t lang) {
    if (lang < 1 || lang > 3) lang = 1;
    set_var_lang(lang);
    eez_flow_set_language_index(ui_lang_to_flow_index_local(lang));
    g_language_refresh_serial++;
    g_force_language_refresh = true;
    if (objects.screen_menu) tick_screen_screen_menu();
    if (objects.screen_setting_general) tick_screen_screen_setting_general();
    if (objects.screen_setting_jack_setting) tick_screen_screen_setting_jack_setting();
    if (objects.screen_setting_admin) tick_screen_screen_setting_admin();
    if (objects.screen_admin_password) tick_screen_screen_admin_password();
    if (objects.screen_update) tick_screen_screen_update();
    if (objects.screen_framware) tick_screen_screen_framware();
    if (objects.screen_password) tick_screen_screen_password();
    if (objects.screen_wifi) tick_screen_screen_wifi();
    g_force_language_refresh = false;
    lv_obj_invalidate(lv_scr_act());
}
