static lv_obj_t *main_brand_labels[4] = {0};
static lv_obj_t *menu_corner_brand = NULL; // آیتم ۴: اسم شرکت + ورژن، گوشهٔ بالا-چپِ منو
static void main_apply_brand_style(lv_obj_t *label) {
    if (!label) return;
    const char *name = company_display_name();
    size_t len = name ? strlen(name) : 0;
    // کادرِ برند ۲۵۰px است؛ تا ۱۱ حرف فونتِ ۳۲، تا ۱۴ حرف فونتِ ۲۸، و برای نام‌های بلندترِ ۱۵-۱۶
    // حرفی (که کاربر خواست جا داشته باشد) فونتِ ۲۴ — وگرنه با LV_LABEL_LONG_CLIP بریده می‌شد.
    const lv_font_t *font = (len >= 15) ? &lv_font_montserrat_24 : (len >= 12 ? &lv_font_montserrat_28 : &lv_font_montserrat_32);
    lv_obj_set_style_text_font(label, font, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_letter_space(label, (len >= 12) ? 0 : 1, LV_PART_MAIN | LV_STATE_DEFAULT);
    // آیتم: کاربر گفت اصلاحِ قبلی (+۶) یک پیکسل زیاد بود؛ به +۵ برگشت.
    lv_obj_set_style_translate_y(label, (len >= 12) ? 5 : 0, LV_PART_MAIN | LV_STATE_DEFAULT);
}
void main_refresh_brand(void) {
    for (int i = 0; i < 4; i++) {
        if (main_brand_labels[i]) {
            main_apply_brand_style(main_brand_labels[i]);
            lv_label_set_text(main_brand_labels[i], company_display_name());
        }
    }
    if (menu_corner_brand) {
        char buf[48];
        snprintf(buf, sizeof(buf), "%s  V.%s", company_display_name(), VERSION);
        lv_label_set_text(menu_corner_brand, buf);
    }
}
