void settings_reset_open_panels(void) {
    if (sg_help_panel) lv_obj_add_flag(sg_help_panel, LV_OBJ_FLAG_HIDDEN);
    if (sg_reset_panel) lv_obj_add_flag(sg_reset_panel, LV_OBJ_FLAG_HIDDEN);
    if (sg_lang_menu) lv_obj_add_flag(sg_lang_menu, LV_OBJ_FLAG_HIDDEN);
    if (sg_lang_backdrop) lv_obj_add_flag(sg_lang_backdrop, LV_OBJ_FLAG_HIDDEN);
    if (sg_pid_menu) lv_obj_add_flag(sg_pid_menu, LV_OBJ_FLAG_HIDDEN);
    if (sg_pid_backdrop) lv_obj_add_flag(sg_pid_backdrop, LV_OBJ_FLAG_HIDDEN);
    if (jack_help_panel) lv_obj_add_flag(jack_help_panel, LV_OBJ_FLAG_HIDDEN);
    if (objects.panle_jack_modify) lv_obj_add_flag(objects.panle_jack_modify, LV_OBJ_FLAG_HIDDEN);
    if (sa_help_panel) lv_obj_add_flag(sa_help_panel, LV_OBJ_FLAG_HIDDEN);
    if (objects.setting_admin_pass_change_panle) lv_obj_add_flag(objects.setting_admin_pass_change_panle, LV_OBJ_FLAG_HIDDEN);
    // setting_admin_pass_change_panle_1 belongs to the admin-password entry screen.
    // Hiding it from the shared settings reset path leaves a blank password page after
    // navigating Info -> Admin more than once.
    if (objects.screen_setting_admin && objects.setting_admin_pass_change_panle_1) {
        lv_obj_add_flag(objects.setting_admin_pass_change_panle_1, LV_OBJ_FLAG_HIDDEN);
    }
    if (jack_time_error_panel) {
        lv_obj_del(jack_time_error_panel);
        jack_time_error_panel = NULL;
    } else if (jack_time_error_backdrop) {
        lv_obj_del(jack_time_error_backdrop);
        jack_time_error_backdrop = NULL;
    }
}
