void jack_touch_beep(void) {
    static uint32_t last_beep_tick = 0;
    uint32_t now = lv_tick_get();
    if (now - last_beep_tick < 120) return;
    last_beep_tick = now;
    if (get_var_setting_general_speaker()) {
        xTaskNotify(buzzerTaskHandle, 2, eSetValueWithOverwrite);
    }
}

// رسم پرچمِ سادهٔ زبانِ انتخاب‌شده داخل کادرِ کوچک کنار dropdown زبان.
// lang: 0=فارسی(ایران) 1=انگلیسی(بریتانیا) 2=ترکی(ترکیه). از مستطیل‌های رنگی استفاده می‌شود.
static void sg_build_lang_flag(lv_obj_t *cont, int lang, lv_coord_t w, lv_coord_t h) {
    if (!cont) return;
    lv_obj_clean(cont);  // پاک‌کردن پرچم قبلی
    lv_obj_clear_flag(cont, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
    if (lang == 0) {
        // ایران: سه نوار افقی سبز/سفید/قرمز
        lv_coord_t y0 = 0;
        const uint32_t cols[3] = {0xff009933, 0xffffffff, 0xffda0000};
        for (int i = 0; i < 3; i++) {
            lv_coord_t sh = (h * (i + 1) / 3) - (h * i / 3);
            lv_obj_t *b = lv_obj_create(cont);
            lv_obj_remove_style_all(b);
            lv_obj_clear_flag(b, LV_OBJ_FLAG_CLICKABLE);
            lv_obj_clear_flag(b, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_set_pos(b, 0, y0);
            lv_obj_set_size(b, w, sh);
            lv_obj_set_style_bg_color(b, lv_color_hex(cols[i]), LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_bg_opa(b, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
            y0 += sh;
        }
    } else if (lang == 2) {
        // ترکیه: زمینه قرمز + هلال و ستاره سفید کاملاً متناسب و وسط‌چین در y = h/2
        lv_obj_t *bg = lv_obj_create(cont);
        lv_obj_remove_style_all(bg);
        lv_obj_clear_flag(bg, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(bg, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_pos(bg, 0, 0);
        lv_obj_set_size(bg, w, h);
        lv_obj_set_style_bg_color(bg, lv_color_hex(0xffe30a17), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(bg, 255, LV_PART_MAIN | LV_STATE_DEFAULT);

        // هلال بیرونی (سفید)
        lv_coord_t d_outer = (h >= 18) ? 14 : 10;
        lv_coord_t y_outer = (h - d_outer) / 2;
        lv_coord_t x_outer = (w >= 26) ? 4 : 2;
        lv_obj_t *circ = lv_obj_create(cont);
        lv_obj_remove_style_all(circ);
        lv_obj_clear_flag(circ, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(circ, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(circ, d_outer, d_outer);
        lv_obj_set_pos(circ, x_outer, y_outer);
        lv_obj_set_style_radius(circ, LV_RADIUS_CIRCLE, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_color(circ, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(circ, 255, LV_PART_MAIN | LV_STATE_DEFAULT);

        // هلال درونی (برش قرمز)
        lv_coord_t d_inner = (h >= 18) ? 11 : 8;
        lv_coord_t y_inner = (h - d_inner) / 2;
        lv_coord_t x_inner = x_outer + ((h >= 18) ? 3 : 2);
        lv_obj_t *circ2 = lv_obj_create(cont);
        lv_obj_remove_style_all(circ2);
        lv_obj_clear_flag(circ2, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(circ2, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(circ2, d_inner, d_inner);
        lv_obj_set_pos(circ2, x_inner, y_inner);
        lv_obj_set_style_radius(circ2, LV_RADIUS_CIRCLE, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_color(circ2, lv_color_hex(0xffe30a17), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(circ2, 255, LV_PART_MAIN | LV_STATE_DEFAULT);

        // ستاره سفید وسط‌چین دقیق در y = h/2
        lv_coord_t st_size = (h >= 18) ? 4 : 3;
        lv_coord_t y_st = (h - st_size) / 2;
        lv_coord_t x_st = (w >= 26) ? 15 : 11;
        lv_obj_t *st = lv_obj_create(cont);
        lv_obj_remove_style_all(st);
        lv_obj_clear_flag(st, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(st, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(st, st_size, st_size);
        lv_obj_set_pos(st, x_st, y_st);
        lv_obj_set_style_bg_color(st, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(st, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_transform_rotation(st, 450, LV_PART_MAIN | LV_STATE_DEFAULT);
    } else {
        // بریتانیا (انگلیسی): زمینه آبی + صلیب سفید + صلیب قرمز نازک‌تر
        lv_obj_t *bg = lv_obj_create(cont);
        lv_obj_remove_style_all(bg);
        lv_obj_clear_flag(bg, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(bg, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_pos(bg, 0, 0);
        lv_obj_set_size(bg, w, h);
        lv_obj_set_style_bg_color(bg, lv_color_hex(0xff012169), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(bg, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
        // صلیب سفید
        lv_obj_t *wv = lv_obj_create(cont);
        lv_obj_remove_style_all(wv);
        lv_obj_clear_flag(wv, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(wv, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(wv, 6, h);
        lv_obj_set_pos(wv, w / 2 - 3, 0);
        lv_obj_set_style_bg_color(wv, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(wv, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_t *wh = lv_obj_create(cont);
        lv_obj_remove_style_all(wh);
        lv_obj_clear_flag(wh, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(wh, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(wh, w, 6);
        lv_obj_set_pos(wh, 0, h / 2 - 3);
        lv_obj_set_style_bg_color(wh, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(wh, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
        // صلیب قرمز نازک‌تر روی صلیب سفید
        lv_obj_t *rv = lv_obj_create(cont);
        lv_obj_remove_style_all(rv);
        lv_obj_clear_flag(rv, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(rv, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(rv, 2, h);
        lv_obj_set_pos(rv, w / 2 - 1, 0);
        lv_obj_set_style_bg_color(rv, lv_color_hex(0xffc8102e), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(rv, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_t *rh = lv_obj_create(cont);
        lv_obj_remove_style_all(rh);
        lv_obj_clear_flag(rh, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(rh, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_size(rh, w, 2);
        lv_obj_set_pos(rh, 0, h / 2 - 1);
        lv_obj_set_style_bg_color(rh, lv_color_hex(0xffc8102e), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(rh, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
}

static void jack_time_error_deleted_cb(lv_event_t *e) {
    (void)e;
    jack_time_error_panel = NULL;
    jack_time_error_close_btn = NULL;
    jack_time_error_bar = NULL;
    jack_time_error_msg_label = NULL;
    jack_time_error_title_label = NULL;
    jack_time_error_subtitle_label = NULL;
    if (jack_time_error_backdrop) {
        lv_obj_del(jack_time_error_backdrop);
        jack_time_error_backdrop = NULL;
    }
    jack_reinforce_error_reason = JACK_REINF_ERR_RULES;
    jack_time_error_start = 0;
    jack_time_error_hold_tick = 0;
    if (jack_time_error_timer) { lv_timer_del(jack_time_error_timer); jack_time_error_timer = NULL; }
}

// مورد ۵: شمارش معکوس ۷ ثانیه‌ای روی نوار؛ در پایان دیالوگ بسته می‌شود
static void jack_time_error_timer_cb(lv_timer_t *t) {
    (void)t;
    if (jack_time_error_hold_tick) {
        jack_time_error_start += lv_tick_elaps(jack_time_error_hold_tick);
        jack_time_error_hold_tick = lv_tick_get();
        return;
    }
    uint32_t el = lv_tick_elaps(jack_time_error_start);
    if (el >= 7000 || !jack_time_error_panel) {
        if (jack_time_error_panel) lv_obj_del(jack_time_error_panel); // deleted_cb تایمر را پاک می‌کند
        return;
    }
    if (jack_time_error_bar) lv_bar_set_value(jack_time_error_bar, (int)(100 - el * 100 / 7000), LV_ANIM_OFF);
}

static void jack_time_error_close_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code != LV_EVENT_CLICKED) return;
    if (!jack_time_error_panel) return;
    jack_touch_beep();
    lv_obj_del(jack_time_error_panel);
}
static void jack_time_error_hold_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_PRESSED) {
        jack_time_error_hold_tick = lv_tick_get();
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        if (jack_time_error_hold_tick) {
            jack_time_error_start += lv_tick_elaps(jack_time_error_hold_tick);
            jack_time_error_hold_tick = 0;
        }
    }
}

static void jack_time_error_ensure_backdrop(bool reinforce) {
    if (!reinforce) {
        if (jack_time_error_backdrop) {
            lv_obj_del(jack_time_error_backdrop);
            jack_time_error_backdrop = NULL;
        }
        return;
    }
    if (!jack_time_error_backdrop || !lv_obj_is_valid(jack_time_error_backdrop)) {
        jack_time_error_backdrop = lv_obj_create(lv_layer_top());
        lv_obj_set_size(jack_time_error_backdrop, 480, 320);
        lv_obj_set_pos(jack_time_error_backdrop, 0, 0);
        lv_obj_clear_flag(jack_time_error_backdrop, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_style_bg_color(jack_time_error_backdrop, lv_color_hex(0x000000), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(jack_time_error_backdrop, 140, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_width(jack_time_error_backdrop, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_add_flag(jack_time_error_backdrop, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(jack_time_error_backdrop, jack_time_error_hold_cb, LV_EVENT_PRESSED, NULL);
        lv_obj_add_event_cb(jack_time_error_backdrop, jack_time_error_hold_cb, LV_EVENT_RELEASED, NULL);
        lv_obj_add_event_cb(jack_time_error_backdrop, jack_time_error_hold_cb, LV_EVENT_PRESS_LOST, NULL);
    }
    lv_obj_clear_flag(jack_time_error_backdrop, LV_OBJ_FLAG_HIDDEN);
}

static void jack_reinforce_sec_text(int32_t ms, char *buf, size_t len) {
    if (ms < 0) ms = 0;
    int32_t sec = (ms + 500) / 1000;
    snprintf(buf, len, "%ld", (long)sec);
}

static void jack_cooling_sec_text(char *buf, size_t len) {
    jack_reinforce_sec_text(get_var_cooling_time() * 1000, buf, len);
}

static const char *get_jack_reinforce_error_title(void) {
    return get_ui_language_index() == 2 ? "Uyari" : (get_ui_language_index() == 1 ? "Notice" : "توجه");
}

static const char *get_jack_reinforce_error_msg(char *buf, size_t len) {
    char cool[8], j1[8], j2[8];
    jack_cooling_sec_text(cool, sizeof(cool));
    bool v1 = false, v2 = false;
    int32_t ms1 = jack_reinforce_text_to_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", &v1);
    int32_t ms2 = jack_reinforce_text_to_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", &v2);
    if (!v1) ms1 = 0;
    if (!v2) ms2 = 0;
    jack_reinforce_sec_text(ms1, j1, sizeof(j1));
    jack_reinforce_sec_text(ms2, j2, sizeof(j2));
    int lang = get_ui_language_index();
    switch (jack_reinforce_error_reason) {
    case JACK_REINF_ERR_COOLING:
        if (lang == 2) snprintf(buf, len, "Cikis suresi sogutma suresinden (%s sn) uzun olamaz.\nGirilen deger en fazla %s sn olacak sekilde duzeltildi.", cool, cool);
        else if (lang == 1) snprintf(buf, len, "Jack time cannot exceed the cooling time (%s sec).\nThe value was corrected to at most %s sec.", cool, cool);
        else snprintf(buf, len, "زمان جک نمی‌تواند از %s ثانیه (زمان خنک‌سازی) بیشتر باشد.\nعدد به حداکثر %s ثانیه اصلاح شد.", cool, cool);
        break;
    case JACK_REINF_ERR_J2_LT_J1:
        if (lang == 2) snprintf(buf, len, "Cikis 2 (%s sn), cikis 1'den (%s sn) kucuk olamaz.\nCikis 2 degeri duzeltildi; tekrar Tamam'a basin.", j2, j1);
        else if (lang == 1) snprintf(buf, len, "Jack 2 (%s sec) cannot be less than Jack 1 (%s sec).\nJack 2 was corrected — tap Confirm again.", j2, j1);
        else snprintf(buf, len, "جک 2 (%s ثانیه) نمی‌تواند از جک 1 (%s ثانیه) کمتر باشد.\nعدد جک 2 اصلاح شد؛ دوباره «تایید» بزنید.", j2, j1);
        break;
    case JACK_REINF_ERR_J1_GT_J2:
        if (lang == 2) snprintf(buf, len, "Cikis 1 (%s sn), cikis 2'den (%s sn) buyuk olamaz.\nCikis 1 degeri duzeltildi; tekrar Tamam'a basin.", j1, j2);
        else if (lang == 1) snprintf(buf, len, "Jack 1 (%s sec) cannot be greater than Jack 2 (%s sec).\nJack 1 was corrected — tap Confirm again.", j1, j2);
        else snprintf(buf, len, "جک 1 (%s ثانیه) نمی‌تواند از جک 2 (%s ثانیه) بیشتر باشد.\nعدد جک 1 اصلاح شد؛ دوباره «تایید» بزنید.", j1, j2);
        break;
    default:
        if (lang == 2) snprintf(buf, len, "Tabla takviye krikolari:\n- Cikis 1 ve 2: 0 ile %s sn (sogutma)\n- Cikis 2, cikis 1'den kucuk olamaz\n- Degeri duzeltin ve Tamam'a basin\n- Hatali deger kaydedilmez; bu sayfa kapanmaz", cool);
        else if (lang == 1) snprintf(buf, len, "Table reinforce jacks:\n- Jack 1 and 2: 0 to %s sec (cooling)\n- Jack 2 must not be less than Jack 1\n- Fix the value and tap Confirm\n- Wrong value is not saved; this page stays open", cool);
        else snprintf(buf, len, "جک های تقویت میز:\n- جک 1 و 2: از 0 تا %s ثانیه (خنک سازی)\n- جک 2 نباید از جک 1 کمتر باشد\n- عدد را اصلاح کنید و «تایید» بزنید\n- اگر عدد اشتباه باشد، ذخیره نمی شود و این صفحه بسته نمی شود", cool);
        break;
    }
    return buf;
}

