static void normalize_num_string(const char *in, char *out, size_t out_len) {
    if (!out || out_len == 0) return;
    out[0] = '\0';
    if (!in) return;
    size_t o = 0;
    for (size_t i = 0; in[i] != '\0' && o + 1 < out_len; ) {
        unsigned char c1 = (unsigned char)in[i];
        if (c1 >= '0' && c1 <= '9') {
            out[o++] = (char)c1;
            i++;
        } else if (c1 == '.' || c1 == ',' || c1 == '/') {
            out[o++] = '.';
            i++;
        } else if (c1 == 0xD8 || c1 == 0xD9 || c1 == 0xDB) {
            if (in[i+1] != '\0') {
                unsigned char c2 = (unsigned char)in[i+1];
                if (c1 == 0xD9 && c2 >= 0xA0 && c2 <= 0xA9) {
                    out[o++] = '0' + (c2 - 0xA0);
                    i += 2;
                } else if (c1 == 0xDB && c2 >= 0xB0 && c2 <= 0xB9) {
                    out[o++] = '0' + (c2 - 0xB0);
                    i += 2;
                } else if (c1 == 0xDB && c2 >= 0x90 && c2 <= 0x99) {
                    out[o++] = '0' + (c2 - 0x90);
                    i += 2;
                } else if (c1 == 0xD9 && c2 == 0xAB) {
                    out[o++] = '.';
                    i += 2;
                } else {
                    i += 2;
                }
            } else {
                i++;
            }
        } else {
            i++;
        }
    }
    out[o] = '\0';
}

static int32_t jack_text_to_ms(const char *text, bool *valid) {
    if (valid) *valid = false;
    if (!text || !*text) return 0;
    char clean[64];
    normalize_num_string(text, clean, sizeof(clean));
    if (clean[0] == '\0') return 0;
    int whole = 0;
    int tenth = -1;
    bool seen_digit = false;
    bool after_dot = false;
    for (const char *p = clean; *p; ++p) {
        char c = *p;
        if (c == '.') {
            if (after_dot) return 0;
            after_dot = true;
            continue;
        }
        if (c < '0' || c > '9') return 0;
        seen_digit = true;
        if (!after_dot) {
            whole = whole * 10 + (c - '0');
        } else if (tenth < 0) {
            tenth = c - '0';
        } else {
            return 0;
        }
    }
    if (!seen_digit) return 0;
    if (tenth < 0) tenth = 0;
    int32_t ms = (whole * 10 + tenth) * 100;
    if (ms < 200 || ms > 8000) return ms;
    if (valid) *valid = true;
    return ms;
}

static int32_t jack_reinforce_text_to_ms(const char *text, bool *valid) {
    if (valid) *valid = false;
    if (!text || !*text) return 0;
    char clean[64];
    normalize_num_string(text, clean, sizeof(clean));
    if (clean[0] == '\0') return 0;
    int whole = 0;
    bool seen_digit = false;
    for (const char *p = clean; *p; ++p) {
        char c = *p;
        if (c == '.') return 0;
        if (c < '0' || c > '9') return 0;
        seen_digit = true;
        whole = whole * 10 + (c - '0');
        if (whole > 999) return 0;
    }
    if (!seen_digit) return 0;
    int32_t ms = whole * 1000;
    if (valid) *valid = true;
    return ms;
}

static int32_t jack_parse_text_ms(const char *text, bool reinforce, bool *valid) {
    return reinforce ? jack_reinforce_text_to_ms(text, valid) : jack_text_to_ms(text, valid);
}

static void jack_reinforce_ms_to_text(int32_t ms, char *buf, size_t len) {
    if (ms < 0) ms = 0;
    int32_t sec = (ms + 500) / 1000;
    snprintf(buf, len, "%ld", (long)sec);
}

static void jack_ms_to_text(int32_t ms, char *buf, size_t len) {
    if (ms < 200) ms = 200;
    if (ms > 8000) ms = 8000;
    int32_t tenths = (ms + 50) / 100;
    snprintf(buf, len, "%ld.%ld", (long)(tenths / 10), (long)(tenths % 10));
}

static void jack_ms_label_from_flow(const char *raw, char *buf, size_t len) {
    if (!raw || !*raw) { buf[0] = '\0'; return; }
    int32_t ms = (int32_t)atoi(raw);
    if (ms < 0) { buf[0] = '\0'; return; }
    if (ms == 0) { snprintf(buf, len, "0.0 (s)"); return; }
    if (ms > 9999) ms = 9999;
    int32_t tenths = (ms + 50) / 100;
    snprintf(buf, len, "%ld.%ld (s)", (long)(tenths / 10), (long)(tenths % 10));
}

static void jack_reinforce_ms_label_from_flow(const char *raw, char *buf, size_t len) {
    if (!raw || !*raw) { buf[0] = '\0'; return; }
    int32_t ms = (int32_t)atoi(raw);
    if (ms < 0) ms = 0;
    int32_t sec = (ms + 500) / 1000;
    snprintf(buf, len, "%ld (s)", (long)sec);
}

static void set_jack_time_text(lv_obj_t *ta, int32_t ms) {
    char buf[8];
    if (jack_is_reinforce_mode) jack_reinforce_ms_to_text(ms, buf, sizeof(buf));
    else jack_ms_to_text(ms, buf, sizeof(buf));
    tick_value_change_obj = ta;
    lv_textarea_set_text(ta, buf);
    tick_value_change_obj = NULL;
}

static void assign_jack_time_ms(void *flowState, int property, int32_t ms) {
    char buf[12];
    snprintf(buf, sizeof(buf), "%ld", (long)ms);
    assignStringProperty(flowState, property, 3, buf, "Failed to assign jack time");
}

static void assign_jack_reinforce_pair_ms(void *flowState, int32_t ms1, int32_t ms2) {
    assign_jack_time_ms(flowState, 53, ms1);
    assign_jack_time_ms(flowState, 54, ms2);
    assign_jack_time_ms(flowState, 32, ms1);
    assign_jack_time_ms(flowState, 33, ms2);
}

static void jack_reinforce_load_into_panel(void *flowState) {
    int32_t ms1 = (int32_t)jack_reinforce_stored_ms1();
    int32_t ms2 = (int32_t)jack_reinforce_stored_ms2();
    char buf[8];
    if (objects.jack_bargasht_holder) {
        jack_reinforce_ms_to_text(ms1, buf, sizeof(buf));
        tick_value_change_obj = objects.jack_bargasht_holder;
        lv_textarea_set_text(objects.jack_bargasht_holder, buf);
        tick_value_change_obj = NULL;
    }
    if (objects.jack_raft_holder) {
        jack_reinforce_ms_to_text(ms2, buf, sizeof(buf));
        tick_value_change_obj = objects.jack_raft_holder;
        lv_textarea_set_text(objects.jack_raft_holder, buf);
        tick_value_change_obj = NULL;
    }
    assign_jack_reinforce_pair_ms(flowState, ms1, ms2);
}

static void jack_reinforce_persist_ms(int32_t ms1, int32_t ms2) {
    jack_reinforce_save_ms((int)ms1, (int)ms2);
}
static int jack_ta_ms(lv_obj_t *ta);

static bool jack_reinforce_clamp_ta(void *flowState, lv_obj_t *edit_ta, bool show_error, bool assign_values) {
    if (!jack_is_reinforce_mode || !edit_ta) return true;
    bool v1 = false, v2 = false;
    int32_t jack1_ms = jack_reinforce_text_to_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", &v1);
    int32_t jack2_ms = jack_reinforce_text_to_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", &v2);
    if (!v1) jack1_ms = 0;
    if (!v2) jack2_ms = 0;

    int32_t cooling_ms = get_var_cooling_time() * 1000;
    if (cooling_ms < 0) cooling_ms = 0;

    int32_t before = (edit_ta == objects.jack_bargasht_holder) ? jack1_ms : jack2_ms;
    bool corrected = false;
    jack_reinf_err_reason_t reason = JACK_REINF_ERR_RULES;

    if (edit_ta == objects.jack_bargasht_holder) {
        if (jack1_ms < 0) { jack1_ms = 0; corrected = true; }
        if (jack1_ms > cooling_ms) { jack1_ms = cooling_ms; corrected = true; reason = JACK_REINF_ERR_COOLING; }
        if (jack1_ms > jack2_ms) { jack1_ms = jack2_ms; corrected = true; reason = JACK_REINF_ERR_J1_GT_J2; }
        if (corrected) set_jack_time_text(objects.jack_bargasht_holder, jack1_ms);
    } else if (edit_ta == objects.jack_raft_holder) {
        if (jack2_ms < 0) { jack2_ms = 0; corrected = true; }
        if (jack2_ms > cooling_ms) { jack2_ms = cooling_ms; corrected = true; reason = JACK_REINF_ERR_COOLING; }
        if (jack2_ms < jack1_ms) { jack2_ms = jack1_ms; corrected = true; reason = JACK_REINF_ERR_J2_LT_J1; }
        if (corrected) set_jack_time_text(objects.jack_raft_holder, jack2_ms);
    }

    if (corrected && before != ((edit_ta == objects.jack_bargasht_holder) ? jack1_ms : jack2_ms)) {
        if (assign_values) {
            assign_jack_reinforce_pair_ms(flowState, jack1_ms, jack2_ms);
        }
        if (show_error) {
            jack_reinforce_error_active = true;
            jack_reinforce_error_reason = reason;
            show_jack_time_error();
        }
    }
    return !corrected;
}

static bool validate_jack_times(bool show_error) {
    bool v1 = false, v2 = false;
    int32_t jack1_ms = jack_parse_text_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", jack_is_reinforce_mode, &v1);
    int32_t jack2_ms = jack_parse_text_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", jack_is_reinforce_mode, &v2);
    bool ok = v1 && v2;
    if (ok && jack_is_reinforce_mode) {
        int32_t cooling_ms = get_var_cooling_time() * 1000;
        ok = (jack1_ms >= 0 && jack1_ms <= cooling_ms && jack2_ms >= jack1_ms && jack2_ms <= cooling_ms);
    }
    if (!ok && show_error) {
        jack_reinforce_error_active = jack_is_reinforce_mode;
        if (jack_is_reinforce_mode) jack_reinforce_error_reason = JACK_REINF_ERR_RULES;
        show_jack_time_error();
    }
    return ok;
}

static bool commit_both_jack_times(void *flowState, bool show_error) {
    if (jack_is_reinforce_mode) {
        lv_obj_t *edit = jack_active_ta ? jack_active_ta : objects.jack_raft_holder;
        bool persist = !show_error;
        bool edit_ok = jack_reinforce_clamp_ta(flowState, edit, show_error, persist);
        lv_obj_t *other = (edit == objects.jack_bargasht_holder) ? objects.jack_raft_holder : objects.jack_bargasht_holder;
        jack_reinforce_clamp_ta(flowState, other, false, persist);
        if (show_error && !edit_ok) return false;
    }
    if (!validate_jack_times(show_error)) return false;
    bool v1 = false, v2 = false;
    int32_t jack1_ms = jack_parse_text_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", jack_is_reinforce_mode, &v1);
    int32_t jack2_ms = jack_parse_text_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", jack_is_reinforce_mode, &v2);
    if (!v1 || !v2) return false;
    if (show_error) {
        set_jack_time_text(objects.jack_bargasht_holder, jack1_ms);
        set_jack_time_text(objects.jack_raft_holder, jack2_ms);
    }
    if (jack_is_reinforce_mode) {
        assign_jack_reinforce_pair_ms(flowState, jack1_ms, jack2_ms);
        jack_reinforce_persist_ms(jack1_ms, jack2_ms);
    } else {
        assign_jack_time_ms(flowState, 53, jack1_ms);
        assign_jack_time_ms(flowState, 54, jack2_ms);
    }
    return true;
}

static bool commit_jack_time_from_ta(void *flowState, lv_obj_t *ta, int property, bool show_error) {
    bool valid = false;
    int32_t ms = jack_is_reinforce_mode ? jack_reinforce_text_to_ms(lv_textarea_get_text(ta), &valid)
                                        : jack_text_to_ms(lv_textarea_get_text(ta), &valid);
    if (valid && jack_is_reinforce_mode) {
        valid = jack_reinforce_clamp_ta(flowState, ta, show_error, true) && validate_jack_times(false);
    }
    if (!valid) {
        if (show_error) {
            jack_reinforce_error_active = jack_is_reinforce_mode;
            show_jack_time_error();
        }
        return false;
    }
    if (show_error) {
        set_jack_time_text(ta, ms);
        if (jack_time_error_panel) {
            lv_obj_del(jack_time_error_panel);
            jack_time_error_panel = NULL;
        }
    }
    if (jack_is_reinforce_mode) {
        bool v1 = false, v2 = false;
        int32_t ms1 = jack_reinforce_text_to_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", &v1);
        int32_t ms2 = jack_reinforce_text_to_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", &v2);
        if (!v1) ms1 = 0;
        if (!v2) ms2 = 0;
        assign_jack_reinforce_pair_ms(flowState, ms1, ms2);
    } else {
        assign_jack_time_ms(flowState, property, ms);
    }
    return true;
}

static void adjust_jack_time(lv_event_t *e, lv_obj_t *ta, int property, int32_t delta_ms) {
    void *flowState = lv_event_get_user_data(e);
    bool valid = false;
    int32_t ms = jack_is_reinforce_mode ? jack_reinforce_text_to_ms(lv_textarea_get_text(ta), &valid)
                                        : jack_text_to_ms(lv_textarea_get_text(ta), &valid);
    if (!valid) ms = jack_is_reinforce_mode ? 0 : 200;
    if (jack_is_reinforce_mode) delta_ms = (delta_ms > 0) ? 1000 : -1000;
    int32_t next = ms + delta_ms;
    bool range_ok = true;
    if (jack_is_reinforce_mode) {
        int32_t cooling_ms = get_var_cooling_time() * 1000;
        if (cooling_ms < 0) cooling_ms = 0;
        int32_t requested = next;
        if (next < 0) next = 0;
        if (next > cooling_ms) next = cooling_ms;
        set_jack_time_text(ta, next);
        bool clean = jack_reinforce_clamp_ta(flowState, ta, true, true);
        if (!clean || requested != next) {
            if (requested != next) {
                bool v1 = false, v2 = false;
                int32_t ms1 = jack_reinforce_text_to_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", &v1);
                int32_t ms2 = jack_reinforce_text_to_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", &v2);
                if (!v1) ms1 = 0;
                if (!v2) ms2 = 0;
                assign_jack_reinforce_pair_ms(flowState, ms1, ms2);
                jack_reinforce_error_active = true;
                jack_reinforce_error_reason = JACK_REINF_ERR_COOLING;
                show_jack_time_error();
            }
            {
                bool v1 = false, v2 = false;
                int32_t ms1 = jack_reinforce_text_to_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", &v1);
                int32_t ms2 = jack_reinforce_text_to_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", &v2);
                if (!v1) ms1 = 0;
                if (!v2) ms2 = 0;
                jack_reinforce_persist_ms(ms1, ms2);
            }
            action_jack_value_set(e);
            return;
        }
        ms = jack_ta_ms(ta);
        next = ms;
    } else {
        range_ok = !(next < 200 || next > 8000);
    }
    if (!range_ok) {
        jack_reinforce_error_active = jack_is_reinforce_mode;
        show_jack_time_error();
        return;
    }
    set_jack_time_text(ta, next);
    if (jack_is_reinforce_mode) {
        bool v1 = false, v2 = false;
        int32_t ms1 = jack_reinforce_text_to_ms(objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "", &v1);
        int32_t ms2 = jack_reinforce_text_to_ms(objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "", &v2);
        if (!v1) ms1 = 0;
        if (!v2) ms2 = 0;
        assign_jack_reinforce_pair_ms(flowState, ms1, ms2);
        jack_reinforce_persist_ms(ms1, ms2);
    } else {
        assign_jack_time_ms(flowState, property, next);
    }
    action_jack_value_set(e);
}

