void main_open_daily_stats(void) {
    event_handler_daily_stats_click(NULL); // این هندلر e را نادیده می‌گیرد، NULL امن است
}

static int get_current_main_mode_id() {
    const char *mode = get_var_enable_mode();
    if (mode && mode[0] == 'F' && mode[1] >= '1' && mode[1] <= '5') {
        return mode[1] - '0';
    }
    return 1;
}

static void event_handler_cb_screen_menu_mode_label(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) {
        return;
    }
    if (get_var_test_mode() || get_var_step_process() || get_var_step_number() > 0 || get_var_josh_is_working() || get_var_cool_is_working()) {
        return;
    }
    int next_mode = get_current_main_mode_id() % 5 + 1;
    e->user_data = (void *)(intptr_t)next_mode;
    action_mode(e);
}

static void event_handler_cb_screen_menu_haffler(lv_event_t *e) {
    static uint32_t press_start_tick = 0;
    static bool long_handled = false;
    static bool suppress_next_click = false;
    lv_event_code_t event = lv_event_get_code(e);

    if (event == LV_EVENT_PRESSED) {
        press_start_tick = lv_tick_get();
        long_handled = false;
        if (get_var_setting_general_speaker()) {
            xTaskNotify(buzzerTaskHandle, 1, eSetValueWithOverwrite);
        }
    } else if (event == LV_EVENT_PRESSING) {
        if (!long_handled && press_start_tick != 0 && (lv_tick_get() - press_start_tick >= 2000U)) {
            long_handled = true;
            suppress_next_click = true;
            if (get_var_step_process() || get_var_step_number() > 0 || get_var_josh_is_working() || get_var_cool_is_working()) {
                return;
            }
            set_var_test_mode(true);
            if (get_var_setting_general_speaker()) {
                xTaskNotify(buzzerTaskHandle, 1, eSetValueWithOverwrite);
            }
        }
    } else if (event == LV_EVENT_CLICKED) {
        jack_touch_beep();
        if (suppress_next_click) {
            suppress_next_click = false;
        } else if (get_var_test_mode()) {
            set_var_test_mode(false);
            clear_test_outputs();
        }
    } else if (event == LV_EVENT_RELEASED || event == LV_EVENT_PRESS_LOST) {
        press_start_tick = 0;
        long_handled = false;
    }
}

static void event_handler_cb_screen_menu_test_lamp(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code != LV_EVENT_PRESSED && code != LV_EVENT_CLICKED) {
        return;
    }

    int id = (int)(intptr_t)lv_event_get_user_data(e);

    // اگر کاربر روی SSR یا سایر لامپ‌ها کلیک کرد ولی هنوز حالت تست روشن نیست،
    // برای SSR یا با تست مود اجازه تغییر وضعیت داده شود
    if (!get_var_test_mode()) {
        if (id == 0) {
            // اجازه تست مستقیم SSR با کلیک روی آیکون SSR در صفحه اصلی
            set_var_test_mode(true);
        } else {
            return;
        }
    }

    static int last_id = -1;
    static uint32_t last_tick = 0;
    uint32_t now = lv_tick_get();
    if (id == last_id && lv_tick_elaps(last_tick) < 80U) {
        return;
    }
    last_id = id;
    last_tick = now;
    switch (id) {
        case 0: set_var_test_ssr(!get_var_test_ssr()); break;
        case 1: set_var_test_shablon(!get_var_test_shablon()); break;
        case 2: set_var_test_safhe(!get_var_test_safhe()); break;
        case 3: set_var_test_press1(!get_var_test_press1()); break;
        case 4: set_var_test_press2(!get_var_test_press2()); break;
        case 5: set_var_test_josh(!get_var_test_josh()); break;
        case 6: set_var_test_zarbe1(!get_var_test_zarbe1()); break;
        case 7: set_var_test_zarbe2(!get_var_test_zarbe2()); break;
        default: break;
    }
    if (get_var_setting_general_speaker()) {
        xTaskNotify(buzzerTaskHandle, 1, eSetValueWithOverwrite);
    }
}

static void to_short_seconds_text(const char *input, char *output, size_t output_size) {
    if (!input || output_size == 0) {
        return;
    }

    long value = 0;
    int sign = 1;
    bool has_digit = false;

    for (const char *p = input; *p; ++p) {
        if (!has_digit && *p == '-') {
            sign = -1;
            continue;
        }

        if (isdigit((unsigned char)*p)) {
            has_digit = true;
            value = (value * 10) + (long)(*p - '0');
        } else if (has_digit) {
            break;
        }
    }

    if (has_digit) {
        snprintf(output, output_size, "%ld S", value * sign);
    } else {
        strncpy(output, input, output_size - 1);
        output[output_size - 1] = '\0';
    }
}

static int32_t parse_dropdown_number(lv_obj_t *dropdown, int32_t fallback_value) {
    if (!dropdown) {
        return fallback_value;
    }

    char text[16];
    lv_dropdown_get_selected_str(dropdown, text, sizeof(text));
    if (text[0] == '\0') {
        return fallback_value;
    }

    return (int32_t)atoi(text);
}

static bool admin_dd_editing(lv_obj_t *dd) {
    if (!dd) return false;
    if (lv_dropdown_is_open(dd)) return true;
    return (lv_obj_get_state(dd) & (LV_STATE_EDITED | LV_STATE_FOCUSED | LV_STATE_PRESSED)) != 0;
}

static void admin_rtc_dropdown_event_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code != LV_EVENT_VALUE_CHANGED) return;
    intptr_t kind = (intptr_t)lv_event_get_user_data(e);
    if (kind <= 1) admin_rtc_mark_time_edited();
    else admin_rtc_mark_date_edited();
}

static void admin_sync_rtc_dropdowns_from_vars(void) {
    if (admin_time_hour_dropdown && !admin_rtc_time_user_edited() && !admin_dd_editing(admin_time_hour_dropdown)) {
        int32_t h = get_var_admin_set_hour();
        if (h < 0 || h > 23) h = 0;
        int32_t sel = (h == 0) ? 23 : h - 1;
        if (lv_dropdown_get_selected(admin_time_hour_dropdown) != sel) {
            tick_value_change_obj = admin_time_hour_dropdown;
            lv_dropdown_set_selected(admin_time_hour_dropdown, sel);
            tick_value_change_obj = NULL;
        }
    }
    if (admin_time_minute_dropdown && !admin_rtc_time_user_edited() && !admin_dd_editing(admin_time_minute_dropdown)) {
        int32_t m = get_var_admin_set_minute();
        if (m < 0 || m > 59) m = 0;
        if (lv_dropdown_get_selected(admin_time_minute_dropdown) != m) {
            tick_value_change_obj = admin_time_minute_dropdown;
            lv_dropdown_set_selected(admin_time_minute_dropdown, m);
            tick_value_change_obj = NULL;
        }
    }
    if (!admin_rtc_date_user_edited()) {
        if (admin_date_month_dropdown && !admin_dd_editing(admin_date_month_dropdown)) {
            int32_t mo = get_var_admin_set_month();
            if (mo < 1 || mo > 12) mo = 1;
            int32_t sel = mo - 1;
            if (lv_dropdown_get_selected(admin_date_month_dropdown) != sel) {
                tick_value_change_obj = admin_date_month_dropdown;
                lv_dropdown_set_selected(admin_date_month_dropdown, sel);
                tick_value_change_obj = NULL;
            }
        }
        if (admin_date_day_dropdown && !admin_dd_editing(admin_date_day_dropdown)) {
            int32_t d = get_var_admin_set_day();
            if (d < 1 || d > 31) d = 1;
            int32_t sel = d - 1;
            if (lv_dropdown_get_selected(admin_date_day_dropdown) != sel) {
                tick_value_change_obj = admin_date_day_dropdown;
                lv_dropdown_set_selected(admin_date_day_dropdown, sel);
                tick_value_change_obj = NULL;
            }
        }
        if (admin_date_year_dropdown && !admin_dd_editing(admin_date_year_dropdown)) {
            int32_t y = get_var_admin_set_year();
            int32_t sel;
            if (get_ui_language_index() != 0) {
                if (y < 2025 || y > 2033) y = 2025;
                sel = y - 2025;
            } else {
                if (y < 1405 || y > 1413) y = 1405;
                sel = y - 1405;
            }
            if (lv_dropdown_get_selected(admin_date_year_dropdown) != sel) {
                tick_value_change_obj = admin_date_year_dropdown;
                lv_dropdown_set_selected(admin_date_year_dropdown, sel);
                tick_value_change_obj = NULL;
            }
        }
    }
    if (sg_temp_err_box) {
        if (sg_temp_err_hold_tick) {
            sg_temp_err_deadline += millis() - sg_temp_err_hold_tick;
            sg_temp_err_hold_tick = millis();
        } else {
            long rem = (long)sg_temp_err_deadline - (long)millis();
            if (rem <= 0) {
                lv_obj_del_async(sg_temp_err_box);
                sg_temp_err_box = NULL;
                sg_temp_err_bar = NULL;
                sg_temp_err_hold_tick = 0;
            } else if (sg_temp_err_bar) {
                lv_bar_set_value(sg_temp_err_bar, (int)(rem * 1000 / 4500), LV_ANIM_OFF);
            }
        }
    }
}

