// نگاشت حالت PID المنت:
// ۰: نرم و دقیق (Soft) -> مقدار عددی ۷
// ۱: هوشمند استاندارد (Normal) -> مقدار عددی ۱۵ (پیش‌فرض کارخانه)
// ۲: قدرتی و سریع (Fast) -> مقدار عددی ۲۵
static const char *get_sg_pid_mode_name(int mode_idx) {
    int lang = get_ui_language_index();
    if (mode_idx == 0) { // Soft
        return lang == 2 ? "Yumusak" : (lang == 1 ? "Soft" : "نرم و دقیق");
    } else if (mode_idx == 2) { // Fast
        return lang == 2 ? "Hizli" : (lang == 1 ? "Fast" : "سریع و قدرتی");
    } else { // Standard (1)
        return lang == 2 ? "Standart" : (lang == 1 ? "Standard" : "استاندارد");
    }
}
static int sg_pid_val_to_mode(int val) {
    if (val <= 10) return 0;       // نرم
    else if (val <= 20) return 1;  // استاندارد
    else return 2;                 // سریع
}
static int sg_pid_mode_to_val(int mode) {
    if (mode == 0) return 7;
    else if (mode == 2) return 25;
    else return 15;
}

