// عنوانِ داخلیِ منوی جک از flow متنِ فارسی می‌دهد؛ اینجا به زبانِ فعلی ترجمه می‌شود
static const char *fix_jack_display_text(const char *text) {
    if (!text) return "";
    if (strcmp(text, "جک صفحه") == 0 || strcmp(text, "جک میز") == 0) return get_jack_label_table();
    if (strcmp(text, "صفحه") == 0 || strcmp(text, "میز") == 0) return get_main_label_plate();
    if (strcmp(text, "جک جوش") == 0 || strcmp(text, "جک المنت") == 0) return get_jack_label_element();
    if (strcmp(text, "جک ضربه") == 0 || strcmp(text, "جک های ضربه") == 0 || strcmp(text, "جک تقویت میز") == 0 || strcmp(text, "جک های تقویت میز") == 0) return get_jack_label_table_reinforce();
    if (strcmp(text, "جوش") == 0 || strcmp(text, "المنت") == 0) return get_main_label_heater();
    if (strcmp(text, "شابلون") == 0) return get_main_label_shablon();
    if (strcmp(text, "جک شابلون") == 0) return get_jack_label_shablon();
    if (strcmp(text, "پروفیل") == 0 || strcmp(text, "جک پروفیل") == 0) return get_ui_language_index() == 2 ? "Profil Kriko" : (get_ui_language_index() == 1 ? "Profile Jack" : "جک پروفیل");
    return text;
}
