static void warranty_jalali_to_gregorian(int jy, int jm, int jd, int *gy, int *gm, int *gd) {
    static const int j_days_in_month[] = {31, 31, 31, 31, 31, 31, 30, 30, 30, 30, 30, 29};
    static const int g_days_in_month[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    long jy2 = jy - 979;
    long jm2 = jm - 1;
    long jd2 = jd - 1;
    long j_day_no = 365 * jy2 + (jy2 / 33) * 8 + ((jy2 % 33 + 3) / 4);
    for (long i = 0; i < jm2; ++i) j_day_no += j_days_in_month[i];
    j_day_no += jd2;
    long g_day_no = j_day_no + 79;
    int y = (int)(1600 + 400 * (g_day_no / 146097));
    g_day_no %= 146097;
    bool leap = true;
    if (g_day_no >= 36525) {
        g_day_no--;
        y += (int)(100 * (g_day_no / 36524));
        g_day_no %= 36524;
        if (g_day_no >= 365) g_day_no++;
        else leap = false;
    }
    y += (int)(4 * (g_day_no / 1461));
    g_day_no %= 1461;
    if (g_day_no >= 366) {
        leap = false;
        g_day_no--;
        y += (int)(g_day_no / 365);
        g_day_no %= 365;
    }
    int i = 0;
    while (g_day_no >= g_days_in_month[i] + ((i == 1 && leap) ? 1 : 0)) {
        g_day_no -= g_days_in_month[i] + ((i == 1 && leap) ? 1 : 0);
        i++;
    }
    *gy = y;
    *gm = i + 1;
    *gd = (int)g_day_no + 1;
}

static void fw_info_get_warranty_display_date(char *buf, int len) {
    char raw[24];
    fw_info_get_warranty_date(raw, sizeof(raw));
    if (get_ui_language_index() == 0) {
        snprintf(buf, len, "%s", raw[0] ? raw : "---");
        return;
    }
    int jy = 0, jm = 0, jd = 0;
    if (sscanf(raw, "%d-%d-%d", &jy, &jm, &jd) == 3 && jy >= 1300 && jy <= 1500) {
        int gy, gm, gd;
        warranty_jalali_to_gregorian(jy, jm, jd, &gy, &gm, &gd);
        snprintf(buf, len, "%04d-%02d-%02d", gy, gm, gd);
        return;
    }
    snprintf(buf, len, "%s", raw[0] ? raw : "---");
}
