const char *get_fw_q_name(int idx) { // آیتم: بدونِ static تا در main.cpp (دیالوگِ جابجاییِ پایه) هم استفاده شود
    // ۸ خروجی، هم‌تراز با fw_out_pins[] (SSR2 وجود ندارد)
    static const char *fa[] = {"میز","پرس-چپ","پرس-راست","المنت","شابلون","SSR1","تقویت میز1","تقویت میز2"};
    static const char *en[] = {"Table","Press-L","Press-R","Element","Shablon","SSR1","Tbl-Reinf1","Tbl-Reinf2"};
    static const char *tr[] = {"Tabla","Pres-Sol","Pres-Sag","Elem","Sablom","SSR1","Takviye1","Takviye2"};
    int lang = get_ui_language_index();
    if (idx < 0 || idx > 7) return "";
    return lang == 2 ? tr[idx] : (lang == 1 ? en[idx] : fa[idx]);
}
const char *get_fw_i_name(int idx) { // آیتم: بدونِ static تا در main.cpp (دیالوگِ جابجاییِ پایه) هم استفاده شود
    static const char *fa[] = {"المنت-باز","المنت-بسته","شابلون-باز","شابلون-بسته","میز-باز","برگشت","استپ اضطراری","استارت-پدال"};
    static const char *en[] = {"Elem-Open","Elem-Close","Sbl-Open","Sbl-Close","Tbl-Open","Back","E-Stop","Start-Pedal"};
    static const char *tr[] = {"Elem-Ac","Elem-Kap","Sabl-Ac","Sabl-Kap","Masa-Ac","Geri","Acil Stop","Start-Pedal"};
    int lang = get_ui_language_index();
    if (idx < 0 || idx > 7) return "";
    return lang == 2 ? tr[idx] : (lang == 1 ? en[idx] : fa[idx]);
}
// آیتم: شمارهٔ اتصالِ چاپ‌شده روی برد (Q0..Q7 / I0..I7) برای نگاشتِ *فعلیِ* هر نام — از main.cpp
extern int fw_conn_q_of_out(int idx);  // -1 = N.C.
extern int fw_conn_i_of_in(int rowIdx); // -1 = N.C.
// نامِ ردیف + شمارهٔ اتصال: «میز  Q0» — اگر قطع باشد «میز  N.C.»
// آیتم: recolorِ اینلاین (#000000 ...#) امتحان شد ولی چیدمانِ راست‌به‌چپ را به‌هم می‌زد (Q/I جلوی
// نام می‌افتاد) و روی N.C. هم اصلاً اثر نمی‌کرد — کاملاً حذف شد؛ متن دوباره ساده و سرجایِ اصلی‌اش است.
static void fw_io_label_text(char *buf, size_t sz, int isOut, int idx) {
    const char *name = isOut ? get_fw_q_name(idx) : get_fw_i_name(idx);
    snprintf(buf, sz, "%s", name);
}
// Qn/In/N.C. rendered in its own fixed-position label (fw_q_code_labels/fw_i_code_labels) so it
// never mixes FA+Latin inside one RTL string (that always put the code in front of the name).
static void fw_io_code_text(char *buf, size_t sz, int isOut, int idx) {
    int c = isOut ? fw_conn_q_of_out(idx) : fw_conn_i_of_in(idx);
    if (c >= 0) snprintf(buf, sz, "%s%s%d", isOut ? "." : "..", isOut ? "Q" : "I", c);
    else        snprintf(buf, sz, "N.C");
}
/* ui_font_kalameh_bold_18 line_height=30 — fixed h=22 caused Persian descenders to clip in LVGL 9 */
#define UI_KALAMEH18_H 30
static void ui_label_kalameh18_h(lv_obj_t * lbl, lv_coord_t w) {
    if (!lbl) return;
    lv_obj_set_size(lbl, w, UI_KALAMEH18_H);
    lv_label_set_long_mode(lbl, LV_LABEL_LONG_CLIP);
}
// چیدمانِ کاملِ یک ردیف (نام + کد + نقطه‌چین) — یک‌جا، تا با تغییرِ زبان در همان لحظه (بدون ریست)
// همه‌چیز درست جابجا شود. قاعده:
// - EN/TR: نام از ابتدای ستون (چپ) شروع، کد دقیقاً بعد از انتهای متنِ نام
// - فارسی: نام چسبیده به لبهٔ راستِ ستون، کد بلافاصله سمتِ چپِ نام (ترتیبِ خواندنِ RTL: نام، نقطه، کد)
// - نقطه‌چین‌ها فضای خالیِ لامپ تا متن را پُر می‌کنند (تعدادِ پویا) و هرگز واردِ متن نمی‌شوند
// ترتیب عمودی ورودی: باز بالای بسته (المنت/شابلون). لامپ و نام و کد باید همیشه یک Y داشته باشند.
static int fw_input_row_y(int idx) {
    if (idx < 0) idx = 0;
    if (idx > 7) idx = 7;
    int y = 2 + idx * 24;
    if (idx == 7) y -= 1; // پدال ۱px بالاتر
    return y;
}
static void fw_io_row_layout(int isOut, int idx) {
    lv_obj_t *nameLbl = isOut ? fw_q_name_labels[idx] : fw_i_name_labels[idx];
    lv_obj_t *codeLbl = isOut ? fw_q_code_labels[idx] : fw_i_code_labels[idx];
    if (!nameLbl || !codeLbl) return;
    bool ltr = (get_ui_language_index() != 0);
    int y = isOut ? (2 + idx * 24) : fw_input_row_y(idx);
    if (isOut && idx == 5) y += 1;     // SSR1 در فارسی/لاتین کمی پایین‌تر خواناتر است
    // لامپ ورودی و خروجی را دقیقاً روی مرکز ردیف (y + 5) هم‌تراز نوشته‌ها قرار بده
    if (!isOut && idx >= 0 && idx < 8 && fw_in_box_lamps[idx])
        lv_obj_set_pos(fw_in_box_lamps[idx], 5, y + 5);
    if (isOut && idx >= 0 && idx < 8 && fw_out_box_lamps[idx])
        lv_obj_set_pos(fw_out_box_lamps[idx], 180, y + 5);
    const char *nm = isOut ? get_fw_q_name(idx) : get_fw_i_name(idx);
    char cbuf[16]; fw_io_code_text(cbuf, sizeof(cbuf), isOut, idx);
    lv_point_t cs; lv_txt_get_size(&cs, cbuf, &ui_font_kalameh_bold_14, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    lv_point_t ts;
    int dotStart = isOut ? (ltr ? 194 : 195) : 20;  // EN/TR خروجی ۵px راست‌تر؛ فارسیِ خروجی هم ۶px راست‌تر (از لامپ به نوشته نرود)
    int dotStep = ltr ? 3 : 5;
    int dotLimit;                     // نقطه‌ها فقط تا قبل از این x مجازند
    if (ltr) {
        int nameX  = isOut ? (211 + 16) : (42 + 8 - (get_ui_language_index() == 1 ? 9 : 0));
        int colEnd = isOut ? 344 : 170;
        int codeReserve = isOut ? ((idx == 2 || idx == 6 || idx == 7) ? 28 : 40) : 24;
        int maxName = colEnd - codeReserve - nameX;      // ورودی‌ها نقطه‌چین ندارند و کمی فضای بیشتر برای فونت بزرگ‌تر می‌گیرند
        // اول فونت ۱۸؛ اگر نامِ بلند جا نشد همان ردیف با فونت ۱۴ (به‌جای بریده‌شدنِ متن)
        const lv_font_t *nf = &ui_font_kalameh_bold_18;
        lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
        if (ts.x + 4 > maxName) {
            nf = &ui_font_kalameh_bold_14;
            lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
        }
        if (isOut && (idx == 6 || idx == 7 || (get_ui_language_index() == 2 && idx == 1))) {
            nf = &ui_font_kalameh_bold_18;
            lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
        }
        if (!isOut) {
            nf = &ui_font_kalameh_bold_14;
            lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
        }
        lv_obj_set_style_text_font(nameLbl, nf, LV_PART_MAIN | LV_STATE_DEFAULT);
        int nw = ts.x + 4; if (nw > maxName) nw = maxName;
        lv_obj_set_pos(nameLbl, nameX, y);
        lv_obj_set_size(nameLbl, nw, UI_KALAMEH18_H);
        lv_obj_set_style_align(nameLbl, LV_ALIGN_TOP_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(nameLbl, LV_TEXT_ALIGN_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_base_dir(nameLbl, LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        int codeX = isOut ? 309 : 135;
        int codeW = isOut ? 30 : 34;
        lv_obj_set_pos(codeLbl, codeX, y + (isOut ? 3 : 4));
        lv_obj_set_size(codeLbl, codeW, 26);
        lv_obj_set_style_align(codeLbl, LV_ALIGN_TOP_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(codeLbl, LV_TEXT_ALIGN_RIGHT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_base_dir(codeLbl, LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        dotLimit = nameX - 2;
    } else {
        int colEnd  = isOut ? 341 : 168;
        int codeW   = isOut ? 25 : 36;
        int gap     = isOut ? 2 : 3;
        int maxName = isOut ? 108 : 104;
        if (isOut && (idx == 2 || idx == 6 || idx == 7)) maxName = 118;
        const lv_font_t *nf = &ui_font_kalameh_bold_18;
        if (!isOut) {
            nf = &ui_font_kalameh_bold_14;
            lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
        } else {
            lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
            if (ts.x + 4 > maxName) {
                nf = &ui_font_kalameh_bold_14;
                lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
            }
            if (idx == 6 || idx == 7) {
                nf = &ui_font_kalameh_bold_18;
                lv_txt_get_size(&ts, nm, nf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
            }
        }
        lv_obj_set_style_text_font(nameLbl, nf, LV_PART_MAIN | LV_STATE_DEFAULT);
        int nw = ts.x + 4; if (nw > maxName) nw = maxName;
        int nx = colEnd - codeW - gap - nw;
        if (!isOut && idx == 7) {
            nx -= 4; // شیفت ۴ پیکسل به چپ در فارسی طبق دستور کاربر تا حرف «ا» برش نخورد
            nw += 6;
        }
        if (!isOut && nx < 20) nx = 20;
        if (isOut && nx < 195) nx = 195;
        lv_obj_set_pos(nameLbl, nx, y);
        lv_obj_set_size(nameLbl, nw, UI_KALAMEH18_H);
        lv_obj_set_style_align(nameLbl, LV_ALIGN_TOP_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(nameLbl, LV_TEXT_ALIGN_RIGHT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_base_dir(nameLbl, LV_BASE_DIR_RTL, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_pos(codeLbl, colEnd - codeW, y + 2);
        lv_obj_set_size(codeLbl, codeW, 26);
        lv_obj_set_style_align(codeLbl, LV_ALIGN_TOP_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(codeLbl, LV_TEXT_ALIGN_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_base_dir(codeLbl, LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        dotLimit = nx - 2;
    }
    // نقطه‌چین‌ها: از لامپ تا نزدیکِ متن — تعدادِ پویا؛ اضافه‌ها مخفی
    for (int d = 0; d < 12; d++) {
        lv_obj_t *dot = isOut ? fw_q_dots[idx][d] : fw_i_dots[idx][d];
        if (!dot) continue;
        int dx = dotStart + d * dotStep;
        lv_obj_set_pos(dot, dx, y + 16);
        int dotCount = isOut ? 8 : 6;
        if (isOut && !ltr && (idx == 6 || idx == 7)) dotCount = 6;
        if (d < dotCount && dx + 3 <= dotLimit) lv_obj_clear_flag(dot, LV_OBJ_FLAG_HIDDEN);
        else                             lv_obj_add_flag(dot, LV_OBJ_FLAG_HIDDEN);
    }
}
/* fw_io_row_layout: fonts/positions/12 dots per row — only rerun when lang or Q/I code changes */
static int32_t fw_io_layout_lang = -1;
static char fw_io_layout_q_code[8][16];
static char fw_io_layout_i_code[8][16];
static void fw_io_layout_cache_reset(void) {
    fw_io_layout_lang = -1;
    for (int i = 0; i < 8; i++) {
        fw_io_layout_q_code[i][0] = '\0';
        fw_io_layout_i_code[i][0] = '\0';
    }
}
static void fw_io_refresh_name_labels(void) {
    char nbuf[48];
    for (int i = 0; i < 8; i++) {
        if (fw_q_name_labels[i]) { fw_io_label_text(nbuf, sizeof(nbuf), 1, i); set_label_if_changed(fw_q_name_labels[i], nbuf); }
        if (fw_i_name_labels[i]) { fw_io_label_text(nbuf, sizeof(nbuf), 0, i); set_label_if_changed(fw_i_name_labels[i], nbuf); }
    }
}
static void fw_io_row_layout_if_needed(int isOut, int idx) {
    char cbuf[16];
    fw_io_code_text(cbuf, sizeof(cbuf), isOut, idx);
    int32_t lang = get_ui_language_index();
    char (*cache)[16] = isOut ? fw_io_layout_q_code : fw_io_layout_i_code;
    lv_obj_t *codeLbl = isOut ? fw_q_code_labels[idx] : fw_i_code_labels[idx];
    if (lang != fw_io_layout_lang) {
        fw_io_layout_lang = lang;
        for (int i = 0; i < 8; i++) {
            fw_io_layout_q_code[i][0] = '\0';
            fw_io_layout_i_code[i][0] = '\0';
        }
    }
    if (strcmp(cache[idx], cbuf) != 0) {
        if (codeLbl) set_label_if_changed(codeLbl, cbuf);
        fw_io_row_layout(isOut, idx);
        lv_strncpy(cache[idx], cbuf, sizeof(cache[idx]));
    }
}
static void fw_io_sync_all_rows(bool refresh_names) {
    if (refresh_names) {
        fw_io_layout_cache_reset();
        fw_io_refresh_name_labels();
    }
    for (int i = 0; i < 8; i++) {
        fw_io_row_layout_if_needed(1, i);
        fw_io_row_layout_if_needed(0, i);
    }
}
// آیتم: نگه‌داشتنِ ۲ ثانیه روی نامِ هر ورودی/خروجی → دیالوگِ جابجاییِ پایه (main.cpp).
// چون این طولانی‌تر از long-press پیش‌فرضِ LVGL (که سراسریه) است، دستی با تیک محاسبه می‌شود.
static uint32_t io_remap_press_start = 0;
static lv_obj_t *io_remap_press_target = NULL;
static bool io_remap_long_fired = false;
static bool io_remap_click_suppress = false; // اگر long-press شلیک شد، تاچِ کوتاهِ بعدی (toggle تست) نادیده گرفته شود
static lv_point_t io_remap_press_point = {0, 0}; // نقطهٔ شروعِ تاچ — برای تشخیصِ اسکرول از نگه‌داشتن
// آیتم: بازخوردِ بصریِ لمس — تا نگه‌داشته‌ای زرد، ول کردی رنگِ اصلیِ خودش (قرمزِ خروجی/سبزِ ورودی) برگردد؛
// این‌طوری کاربر می‌فهمد دقیقاً کجا را دارد لمس می‌کند.
static lv_color_t io_remap_label_default_color(lv_event_t *e) {
    lv_obj_t *target = lv_event_get_target(e);
    int enc = (int)(intptr_t)lv_event_get_user_data(e);
    bool isOut = enc >= 0;
    int idx = isOut ? enc : (-enc - 1);
    // کدِ لیبل (Qn/In/N.C.) همیشه مشکی می‌ماند — رنگِ قرمز/سبز فقط برای لیبلِ نام است
    lv_obj_t *codeLbl = isOut ? (idx >= 0 && idx < 9 ? fw_q_code_labels[idx] : NULL)
                              : (idx >= 0 && idx < 8 ? fw_i_code_labels[idx] : NULL);
    if (target == codeLbl) return lv_color_hex(0xff000000);
    return lv_color_hex(isOut ? 0xffd02020 : 0xff1f8f3a);
}
static void event_handler_io_remap_press(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t *target = lv_event_get_target(e);
    if (code == LV_EVENT_PRESSED) {
        io_remap_press_start = lv_tick_get();
        io_remap_press_target = target;
        io_remap_long_fired = false;
        lv_indev_get_point(lv_indev_get_act(), &io_remap_press_point);
        lv_obj_set_style_text_color(target, lv_color_hex(0xffffcc00), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (code == LV_EVENT_PRESSING) {
        if (io_remap_press_target == target && !io_remap_long_fired) {
            lv_point_t p;
            lv_indev_get_point(lv_indev_get_act(), &p);
            int32_t dx = p.x - io_remap_press_point.x;
            int32_t dy = p.y - io_remap_press_point.y;
            // اگر انگشت جابه‌جا شد یعنی قصدِ اسکرول‌کردنِ صفحه دارد نه نگه‌داشتنِ روی نوشته —
            // از زمان‌گیریِ منوی جابجاییِ پایه خارج شو (دیگر تا رهاکردن و لمسِ دوباره فعال نمی‌شود).
            if (dx * dx + dy * dy > 400) { // ~۲۰px — ردیف‌های پایین (I6/I7) با اسکرول لرزش جزئی دارند
                io_remap_press_target = NULL;
                lv_obj_set_style_text_color(target, io_remap_label_default_color(e), LV_PART_MAIN | LV_STATE_DEFAULT);
            } else if (lv_tick_elaps(io_remap_press_start) >= 2000) {
                io_remap_long_fired = true;
                io_remap_click_suppress = true;
                int enc = (int)(intptr_t)lv_event_get_user_data(e);
                // آیتم بوق: این یک سناریوِ «نگه‌داشتنی» است — با بازشدنِ دیالوگ ۳ بوقِ کوتاه، نه ۲تا
                // (enumِ buzzer_event_t در tasks.h است که اینجا include نمی‌شود؛ ۵=BUZZER_IMPORTANT
                // مثلِ همین الگو در jack_touch_beep که از عددِ خام ۲=BUZZER_CONFIRM استفاده می‌کند)
                xTaskNotify(buzzerTaskHandle, 5, eSetValueWithOverwrite);
                lv_obj_set_style_text_color(target, io_remap_label_default_color(e), LV_PART_MAIN | LV_STATE_DEFAULT);
                io_remap_dialog_open(enc >= 0 ? 1 : 0, enc >= 0 ? enc : (-enc - 1));
            }
        }
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        io_remap_press_target = NULL;
        lv_obj_set_style_text_color(target, io_remap_label_default_color(e), LV_PART_MAIN | LV_STATE_DEFAULT);
    }
}
static void event_handler_fw_out_lamp(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    if (io_remap_click_suppress) { io_remap_click_suppress = false; return; } // این کلیک نتیجهٔ long-press بود
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    jack_touch_beep();
    fw_info_toggle_digital_out(idx);
}
// آیتم: نگه‌داشتنِ ۲ ثانیه رویِ عنوانِ «ورودی»/«خروجی» → دیالوگِ بازگردانیِ همهٔ پایه‌های آن دسته به حالتِ کارخانه
static uint32_t io_reset_press_start = 0;
static lv_obj_t *io_reset_press_target = NULL;
static bool io_reset_long_fired = false;
static lv_color_t io_reset_label_default_color(lv_event_t *e) {
    int isOutput = (int)(intptr_t)lv_event_get_user_data(e);
    return lv_color_hex(isOutput ? 0xffd02020 : 0xff1f8f3a);
}
static void event_handler_io_reset_press(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t *target = lv_event_get_target(e);
    if (code == LV_EVENT_PRESSED) {
        io_reset_press_start = lv_tick_get();
        io_reset_press_target = target;
        io_reset_long_fired = false;
        // آیتم: تا انگشتِ کاربر روی نوشتهٔ ورودی/خروجی هست، رنگش زرد شود تا فشرده‌شدن حس شود
        lv_obj_set_style_text_color(target, lv_color_hex(0xffffcc00), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (code == LV_EVENT_PRESSING) {
        if (io_reset_press_target == target && !io_reset_long_fired && lv_tick_elaps(io_reset_press_start) >= 2000) {
            io_reset_long_fired = true;
            int isOutput = (int)(intptr_t)lv_event_get_user_data(e);
            xTaskNotify(buzzerTaskHandle, 5, eSetValueWithOverwrite); // ۳ بوقِ کوتاه = سناریوِ نگه‌داشتنی باز شد
            lv_obj_set_style_text_color(target, io_reset_label_default_color(e), LV_PART_MAIN | LV_STATE_DEFAULT);
            io_reset_dialog_open(isOutput);
        }
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        io_reset_press_target = NULL;
        lv_obj_set_style_text_color(target, io_reset_label_default_color(e), LV_PART_MAIN | LV_STATE_DEFAULT);
    }
}
