static void event_handler_frames_reset_confirm(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    set_var_frame_numbers(0);
    close_frames_reset_dlg();
}
static void event_handler_frames_reset_cancel(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    close_frames_reset_dlg();
}
static void event_handler_warranty_btn_click(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    fw_info_activate_warranty();   // تاریخِ همان لحظهٔ ساعت را ثبت می‌کند
    if (fw_info_warranty_is_active()) {
        if (fw_warranty_btn) lv_obj_add_flag(fw_warranty_btn, LV_OBJ_FLAG_HIDDEN);
        if (fw_warranty_title_label) lv_obj_clear_flag(fw_warranty_title_label, LV_OBJ_FLAG_HIDDEN);
        if (fw_warranty_date_label) {
            char buf[24];
            fw_info_get_warranty_display_date(buf, sizeof(buf));
            lv_label_set_text(fw_warranty_date_label, buf[0] ? buf : "---");
            lv_obj_clear_flag(fw_warranty_date_label, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_pos(fw_warranty_date_label, 176, 104);
        }
        if (fw_warranty_title_label) lv_obj_set_pos(fw_warranty_title_label, 251, 103);
    }
}

