// فقط فلگ ست می‌شود؛ پردازشِ واقعی در tick_screen_screen_update
static volatile bool g_self_update_pressed = false;
static lv_obj_t *fw_webapp_dialog = NULL;

static void fw_webapp_dialog_close(void) {
    if (fw_webapp_dialog && lv_obj_is_valid(fw_webapp_dialog)) {
        lv_obj_del(fw_webapp_dialog);
    }
    fw_webapp_dialog = NULL;
}

static void event_handler_webapp_dialog_confirm(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    fw_webapp_dialog_close();
    webapp_disconnect_for_update();
    start_info_self_update();
    eez_flow_set_screen(SCREEN_ID_SCREEN_WIFI, LV_SCR_LOAD_ANIM_NONE, 0, 0);
}

static void event_handler_webapp_dialog_cancel(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    fw_webapp_dialog_close();
}

static void fw_webapp_dialog_open(void) {
    fw_webapp_dialog_close();
    int lang = get_ui_language_index();

    lv_obj_t *dlg = lv_obj_create(lv_scr_act());
    fw_webapp_dialog = dlg;
    lv_obj_set_size(dlg, 420, 240);
    lv_obj_center(dlg);
    lv_obj_clear_flag(dlg, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_radius(dlg, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(dlg, lv_color_hex(0xff1e293b), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_color(dlg, lv_color_hex(0xff38bdf8), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(dlg, 2, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(dlg, 16, LV_PART_MAIN | LV_STATE_DEFAULT);

    // عنوان
    lv_obj_t *ttl = lv_label_create(dlg);
    lv_label_set_text(ttl, lang == 2 ? "Web Baglantisi Kesilecek" : (lang == 1 ? "Disconnect WebApp" : "هشدار قطع ارتباط وب‌اپ"));
    lv_obj_align(ttl, LV_ALIGN_TOP_MID, 0, 0);
    lv_obj_set_style_text_color(ttl, lv_color_hex(0xff38bdf8), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_font(ttl, &ui_font_kalameh_bold_18, LV_PART_MAIN | LV_STATE_DEFAULT);

    // متن توضیحات
    lv_obj_t *msg = lv_label_create(dlg);
    lv_obj_set_width(msg, 380);
    lv_label_set_long_mode(msg, LV_LABEL_LONG_WRAP);
    lv_obj_align(msg, LV_ALIGN_TOP_MID, 0, 42);
    lv_obj_set_style_text_align(msg, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_color(msg, lv_color_hex(0xfff1f5f9), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_font(msg, &ui_font_kalame_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
    if (lang == 0) {
        lv_obj_set_style_base_dir(msg, LV_BASE_DIR_RTL, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_text(msg, "گوشی شما در حال حاضر به وب‌اپ دستگاه متصل است.\nجهت اسکن وای‌فای و بروزرسانی، ارتباط با گوشی قطع خواهد شد.\nآیا ادامه می‌دهید؟");
    } else if (lang == 2) {
        lv_obj_set_style_base_dir(msg, LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_text(msg, "Telefonunuz WebApp'e bagli.\nWiFi taramasi ve guncelleme icin baglanti kesilecek.\nDevam edilsin mi?");
    } else {
        lv_obj_set_style_base_dir(msg, LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_text(msg, "Your phone is connected to the WebApp.\nTo scan WiFi and update, web connection will disconnect.\nDo you want to continue?");
    }

    // دکمه تایید (سبز)
    lv_obj_t *btn_ok = lv_btn_create(dlg);
    lv_obj_set_size(btn_ok, 140, 42);
    lv_obj_align(btn_ok, LV_ALIGN_BOTTOM_RIGHT, -10, 0);
    lv_obj_set_style_radius(btn_ok, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(btn_ok, lv_color_hex(0xff16a34a), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(btn_ok, event_handler_webapp_dialog_confirm, LV_EVENT_CLICKED, NULL);
    lv_obj_t *lbl_ok = lv_label_create(btn_ok);
    lv_label_set_text(lbl_ok, lang == 2 ? "Evet / Devam" : (lang == 1 ? "Confirm" : "تایید و قطع"));
    lv_obj_center(lbl_ok);
    lv_obj_set_style_text_font(lbl_ok, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);

    // دکمه انصراف (قرمز)
    lv_obj_t *btn_cn = lv_btn_create(dlg);
    lv_obj_set_size(btn_cn, 140, 42);
    lv_obj_align(btn_cn, LV_ALIGN_BOTTOM_LEFT, 10, 0);
    lv_obj_set_style_radius(btn_cn, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(btn_cn, lv_color_hex(0xffdc2626), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(btn_cn, event_handler_webapp_dialog_cancel, LV_EVENT_CLICKED, NULL);
    lv_obj_t *lbl_cn = lv_label_create(btn_cn);
    lv_label_set_text(lbl_cn, lang == 2 ? "Iptal" : (lang == 1 ? "Cancel" : "انصراف"));
    lv_obj_center(lbl_cn);
    lv_obj_set_style_text_font(lbl_cn, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
}

static void event_handler_update_btn_click(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    if (webapp_is_client_connected()) {
        fw_webapp_dialog_open();
    } else {
        g_self_update_pressed = true;
    }
}

