static void fw_sysbar_btn_update_style(void) {
    if (!fw_sysbar_btn || !fw_sysbar_btn_label) return;
    bool en = storage_get_sysbar_enabled();
    int lang = get_ui_language_index();
    const char *title = (lang == 1) ? "System Info" : ((lang == 2) ? "Sistem Bilgisi" : "اطلاعات سیستم");
    set_label_if_changed(fw_sysbar_btn_label, title);
    if (en) {
        // حالت پررنگ و فعال (Bright / Active)
        lv_obj_set_style_bg_color(fw_sysbar_btn, lv_color_hex(0xff1b5e20), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(fw_sysbar_btn, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(fw_sysbar_btn_label, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_opa(fw_sysbar_btn_label, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_width(fw_sysbar_btn, 1, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_color(fw_sysbar_btn, lv_color_hex(0xff4caf50), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_opa(fw_sysbar_btn, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
    } else {
        // حالت کم‌رنگ و ملایم (Dimmed / Legible) طبق درخواست کاربر: متن کاملاً سفید و خوانا می‌ماند
        lv_obj_set_style_bg_color(fw_sysbar_btn, lv_color_hex(0xff1b5e20), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(fw_sysbar_btn, 110, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(fw_sysbar_btn_label, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_opa(fw_sysbar_btn_label, 230, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_width(fw_sysbar_btn, 1, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_color(fw_sysbar_btn, lv_color_hex(0xff4caf50), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_border_opa(fw_sysbar_btn, 80, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
}

static void event_handler_sysbar_btn_click(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    bool en = !storage_get_sysbar_enabled();
    storage_set_sysbar_enabled(en);
#if LV_USE_SYSMON && LV_USE_PERF_MONITOR
    if (en) {
        lv_sysmon_show_performance(NULL);
    } else {
        lv_sysmon_hide_performance(NULL);
    }
#endif
    fw_sysbar_btn_update_style();
}

static void event_handler_firmware_back_click(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    fw_info_reset_manual_outputs();
    if (get_var_ota_enable()) {
        safe_return_from_ota_to_menu();
    } else {
        // FIX-WEBAPP-AP: در حالت عادی (non-F5)، self_update_task را متوقف کن
        // تا webapp/AP پس از بازگشت به SCREEN_UPDATE بلافاصله بالا بیاید.
        cancel_info_self_update();
    }
    eez_flow_set_screen(SCREEN_ID_SCREEN_UPDATE, LV_SCR_LOAD_ANIM_NONE, 0, 0);
}

static void event_handler_frames_reset_click(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    lv_obj_t *target = lv_event_get_target(e);
    if (code == LV_EVENT_PRESSED && target) {
        lv_obj_set_style_text_color(target, lv_color_hex(0xffffcc00), LV_PART_MAIN | LV_STATE_DEFAULT);
        return;
    }
    if ((code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) && target) {
        lv_obj_set_style_text_color(target, lv_color_hex(target == info_frames_label ? 0xff1565c0 : 0xff000000), LV_PART_MAIN | LV_STATE_DEFAULT);
        return;
    }
    if (code != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    if (frames_reset_dlg) return;
    lv_obj_t *par = lv_layer_top();
    frames_reset_dlg = lv_obj_create(par);
    lv_obj_add_flag(frames_reset_dlg, LV_OBJ_FLAG_FLOATING);
    lv_obj_set_size(frames_reset_dlg, 310, 130);
    lv_obj_align(frames_reset_dlg, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_color(frames_reset_dlg, lv_color_hex(0xff1a2535), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(frames_reset_dlg, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_color(frames_reset_dlg, lv_color_hex(0xff445577), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(frames_reset_dlg, 2, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(frames_reset_dlg, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(frames_reset_dlg, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_clear_flag(frames_reset_dlg, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(frames_reset_dlg, autoclose_hold_event_cb, LV_EVENT_ALL, &frames_reset_hold_tick);
    // question text
    lv_obj_t *qlbl = lv_label_create(frames_reset_dlg);
    lv_obj_set_size(qlbl, 290, LV_SIZE_CONTENT);
    lv_obj_align(qlbl, LV_ALIGN_TOP_MID, 0, 2);
    lv_obj_set_style_text_color(qlbl, lv_color_hex(0xffd0e8ff), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_font(qlbl, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_align(qlbl, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_base_dir(qlbl, (get_ui_language_index() == 0) ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(qlbl, get_ui_language_index()==2?"Su ana kadar kaynaklanan cerceve sayisini sifirlamak istiyor musunuz?"
                           :(get_ui_language_index()==1?"Reset the total number of frames welded so far?":"آیا قصد دارید تعداد چهارچوب هایی که تا کنون جوش داده اید را صفر کنید؟"));
    // confirm button — پایین‌چپ
    lv_obj_t *ok_btn = lv_btn_create(frames_reset_dlg);
    frames_reset_ok_btn = ok_btn;
    lv_obj_set_size(ok_btn, 138, 42);
    lv_obj_align(ok_btn, LV_ALIGN_BOTTOM_LEFT, 0, -12);
    lv_obj_set_style_bg_color(ok_btn, lv_color_hex(0xff1a4880), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(ok_btn, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(ok_btn, event_handler_frames_reset_confirm, LV_EVENT_CLICKED, NULL);
    lv_obj_t *ok_lbl = lv_label_create(ok_btn);
    lv_obj_align(ok_lbl, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_text_font(ok_lbl, &ui_font_kalameh_bold_18, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_base_dir(ok_lbl, LV_BASE_DIR_RTL, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(ok_lbl, get_ui_language_index()==2?"Onayla"
                             :(get_ui_language_index()==1?"Confirm":"تأیید"));
    // ۵ ثانیه شمارش معکوس — دقیقاً مثلِ دیالوگِ ریست‌فکتوری: نوارِ خاکستری با اندیکاتورِ قرمز که
    // پُر می‌شود، و کلیدِ انصرافِ کوچک‌ترِ خاکستری به‌صورتِ مرکزی روی نوار قرار دارد (فرزندِ نوار).
    frames_reset_bar = lv_bar_create(frames_reset_dlg);
    lv_obj_set_size(frames_reset_bar, 138, 42);
    lv_obj_align(frames_reset_bar, LV_ALIGN_BOTTOM_RIGHT, 4, -12);
    lv_bar_set_range(frames_reset_bar, 0, 100);
    lv_bar_set_value(frames_reset_bar, 0, LV_ANIM_OFF);
    lv_obj_set_style_bg_color(frames_reset_bar, lv_color_hex(0xffd9dde1), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(frames_reset_bar, lv_color_hex(0xffd23b3b), LV_PART_INDICATOR | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(frames_reset_bar, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(frames_reset_bar, 4, LV_PART_MAIN | LV_STATE_DEFAULT);
    {
        lv_obj_t *cancel_btn = lv_btn_create(frames_reset_bar);
        frames_reset_cancel_btn = cancel_btn;
        lv_obj_set_size(cancel_btn, 122, 26); // کوچک‌تر تا نوارِ پرشونده‌ی شمارش‌معکوس دورِ انصراف دیده شود
        lv_obj_center(cancel_btn);
        lv_obj_set_style_bg_color(cancel_btn, lv_color_hex(0xff8a949c), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_radius(cancel_btn, 6, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_add_event_cb(cancel_btn, event_handler_frames_reset_cancel, LV_EVENT_CLICKED, NULL);
        lv_obj_t *cancel_lbl = lv_label_create(cancel_btn);
        lv_obj_center(cancel_lbl);
        lv_obj_set_style_text_font(cancel_lbl, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_base_dir(cancel_lbl, LV_BASE_DIR_RTL, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_text(cancel_lbl, get_ui_language_index()==2?"Iptal":(get_ui_language_index()==1?"Cancel":"انصراف"));
    }
    frames_reset_tick = lv_tick_get();
    frames_reset_hold_tick = 0;
}

static void event_handler_cb_screen_splash_screen_splash(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_SCREEN_LOAD_START) {
        // group: jjj
        lv_group_remove_all_objs(groups.jjj);
    }
    if (event == LV_EVENT_SCREEN_LOADED) {
        e->user_data = (void *)0;
        flowPropagateValueLVGLEvent(flowState, 1, 0, e);
    }
}

static void event_handler_cb_screen_menu_screen_menu(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_SCREEN_LOAD_START) {
        // group: jjj
        lv_group_remove_all_objs(groups.jjj);
        lv_group_add_obj(groups.jjj, objects.obj14);
        lv_group_add_obj(groups.jjj, objects.setting_imageicon);
        // بازگشت به صفحهٔ اصلی → قفل مدیر دوباره فعال (دفعهٔ بعد رمز بخواهد)
        fw_admin_set_unlocked(false);
        s_main_idle_last_tick = 0;
    }
    if (event == LV_EVENT_SCREEN_LOADED) {
        if (get_var_setting_general_speaker() && buzzerTaskHandle) {
            xTaskNotify(buzzerTaskHandle, 4, eSetValueWithOverwrite);
        }
        e->user_data = (void *)0;
        action_main_load(e);
    }
    if (event == LV_EVENT_PRESSED) {
        if (main_intro_is_active()) {
            main_intro_gauge_done = true;
            main_intro_gauge_boot_played = true;
        }
    }
}

// Drag on the temperature meter to set the target temperature (like turning a car dial).
static void temp_meter_target_drag_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    static bool target_changed = false;
    if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        s_gauge_is_dragging = false;
        if (target_changed) {
            // همگام‌سازی نهایی کمان هدف (در درگ برای سرعت کمتر به‌روز شده)
            set_main_temp_target_arc_now(get_var_element_temperature_target());
            action_element_temp_target_changed(e);
            target_changed = false;
        }
        return;
    }
    if (code != LV_EVENT_PRESSING && code != LV_EVENT_PRESSED) return;
    if (main_intro_is_active()) {
        main_intro_gauge_done = true;
        main_intro_gauge_boot_played = true;
    }
    if (is_cycle_time_edit_locked() || get_var_test_mode()) return;

    static uint32_t s_last_drag_tick = 0;
    if (code == LV_EVENT_PRESSING) {
        if (lv_tick_elaps(s_last_drag_tick) < 25U) return;
        s_last_drag_tick = lv_tick_get();
    }
    s_gauge_is_dragging = true;

    lv_indev_t *indev = lv_indev_get_act();
    if (!indev) return;
    lv_point_t p;
    lv_indev_get_point(indev, &p);
    lv_obj_t *m = lv_event_get_target(e);
    lv_area_t a;
    lv_obj_get_coords(m, &a);
    float cx = (float)(a.x1 + a.x2) / 2.0f;
    float cy = (float)(a.y1 + a.y2) / 2.0f;
    // فقط روی حلقهٔ خط‌چین (بین دیسک سفید مرکزی و لبه خارجی) تا لمس به راحتی دریافت شود
    float ddx = (float)p.x - cx, ddy = (float)p.y - cy;
    float dist_sq = ddx * ddx + ddy * ddy;
    const float ring_inner_sq = 75.0f * 75.0f;   // 5625.0f
    const float ring_outer_sq = 145.0f * 145.0f; // 21025.0f
    if (dist_sq < ring_inner_sq || dist_sq > ring_outer_sq) return;
    float ang = atan2f(ddy, ddx) * 57.2957795f;
    if (ang < 0.0f) ang += 360.0f;
    float rel = ang - 135.0f;
    if (rel < 0.0f) rel += 360.0f;
    if (rel > 270.0f) return;
    int32_t val = (int32_t)((rel / 270.0f) * 350.0f + 0.5f);
    if (val < 0) val = 0;
    if (val > 350) val = 350;
    if (val == get_var_element_temperature_target()) return;
    static uint32_t last_beep = 0;
    if (get_var_setting_general_speaker() && (code == LV_EVENT_PRESSED || lv_tick_elaps(last_beep) > 280U)) {
        xTaskNotify(buzzerTaskHandle, 1, eSetValueWithOverwrite);
        last_beep = lv_tick_get();
    }
    set_var_element_temperature_target(val);
    uint32_t target_col = get_temp_gradient_color(val);
    // عدد هدف و عقربه هدف فوری
    if (objects.obj12) {
        char text[24];
        snprintf(text, sizeof(text), "\xE2\x80\x8E%ld\xC2\xB0", (long)val);
        set_label_if_changed(objects.obj12, text);
        static uint32_t last_drag_text_col = 0;
        if (target_col != last_drag_text_col) {
            last_drag_text_col = target_col;
            lv_obj_set_style_text_color(objects.obj12, lv_color_hex(target_col), LV_PART_MAIN | LV_STATE_DEFAULT);
        }
    }
    main_update_temp_target_needle(val);
    if (objects.temputre_arcs && tick_value_change_obj != objects.temputre_arcs) {
        if (lv_arc_get_value(objects.temputre_arcs) != val) {
            tick_value_change_obj = objects.temputre_arcs;
            lv_arc_set_value(objects.temputre_arcs, val);
            tick_value_change_obj = NULL;
        }
        static uint32_t last_drag_arc_col = 0;
        if (target_col != last_drag_arc_col) {
            last_drag_arc_col = target_col;
            lv_obj_set_style_arc_color(objects.temputre_arcs, lv_color_hex(target_col), LV_PART_INDICATOR | LV_STATE_DEFAULT);
        }
    }
    {
        static uint32_t last_arc_upd = 0;
        if (code == LV_EVENT_PRESSED || last_arc_upd == 0 || lv_tick_elaps(last_arc_upd) >= 50U) {
            if (objects.obj10 && lv_arc_get_value(objects.obj10) != val) {
                tick_value_change_obj = objects.obj10;
                lv_arc_set_value(objects.obj10, val);
                tick_value_change_obj = NULL;
            }
            last_arc_upd = lv_tick_get();
        }
    }
    target_changed = true;
}

static void event_handler_cb_screen_menu_temputre_arcs(lv_event_t *e) {
    if (is_cycle_time_edit_locked() || get_var_test_mode()) {
        return;
    }
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_PRESSED && get_var_setting_general_speaker()) {
        xTaskNotify(buzzerTaskHandle, 1, eSetValueWithOverwrite);
    }
    if (event == LV_EVENT_VALUE_CHANGED) {
        if (s_gauge_is_dragging || is_numeric_button_touch_recent()) {
            return;
        }
        lv_obj_t *ta = lv_event_get_target(e);
        if (tick_value_change_obj != ta) {
            int32_t value = lv_arc_get_value(ta);
            set_var_element_temperature_target(value);
            set_main_temp_target_arc_now(value);
        }
    }
    if (event == LV_EVENT_RELEASED || event == LV_EVENT_PRESS_LOST) {
        s_gauge_is_dragging = false;
        e->user_data = (void *)0;
        action_element_temp_target_changed(e);
    }
}

