// -------------------------------------------------------------
// گارد تغییرات ذخیره‌نشده و کلید ذخیره پویا (سبز <-> آبی)
// -------------------------------------------------------------
static bool sg_is_dirty(void) {
    if (get_var_setting_general_speaker() != sg18_speaker) return true;
    if (get_var_setting_general_automatic_start() != sg18_auto_start) return true;
    if (get_var_setting_general_final_jack() != sg18_final_jack) return true;
    if (get_var_setting_general_temperature_limit() != sg18_temp_limit) return true;
    if (get_var_setting_general_pid() != sg18_pid) return true;
    if (get_var_setting_general_pedal_number3() != sg18_tree_pedal) return true;
    if (get_var_setting_general_wifi() != sg18_wifi) return true;
    if (get_var_lang() != sg18_orig_lang) return true;
    if (get_var_setting_general_temperature_caliber() != sg18_temp_caliber) return true;
    return false;
}

static bool sa_is_dirty(void) {
    if (get_var_setting_admin_thermocouple_j() != sa_snap_tc_j) return true;
    if (get_var_setting_admin_emergency_switch() != sa_snap_emerg) return true;
    if (get_var_setting_admin_jack_sensor() != sa_snap_sensor) return true;
    if (admin_countdown_draft_days() != sa_snap_days) return true;
    const char *p1 = get_var_setting_admin_password_placeholder();
    const char *p2 = get_var_setting_admin_re_enter_password_placeholder();
    if (p1 && p1[0] != '\0') return true;
    if (p2 && p2[0] != '\0') return true;
    if (admin_rtc_time_user_edited() || admin_rtc_date_user_edited()) return true;
    return false;
}

static lv_obj_t *unsaved_modal_bg = NULL;
static lv_obj_t *unsaved_bar = NULL;
static lv_obj_t *unsaved_title_label = NULL;
static lv_obj_t *unsaved_msg_label = NULL;
static lv_obj_t *unsaved_ok_label = NULL;
static lv_obj_t *unsaved_cancel_label = NULL;
static uint32_t unsaved_start_tick = 0;
static uint32_t unsaved_hold_tick = 0;
static int unsaved_source_screen_id = 0;
static int unsaved_target_screen_id = 0;

static const char *get_unsaved_title_text(void) {
    int lang = get_ui_language_index();
    if (lang == 2) return "Degisiklikler Kaydedilsin mi?";
    if (lang == 1) return "Save Changes?";
    return "ذخیره تغییرات؟";
}

static const char *get_unsaved_msg_text(void) {
    int lang = get_ui_language_index();
    if (lang == 2) return "Kaydedilmemis degisiklikler var. Kaydedilsin mi?";
    if (lang == 1) return "You have unsaved changes. Do you want to save them?";
    return "تغییرات ذخیره نشده است. آیا تغییرات ذخیره شوند؟";
}

static void unsaved_modal_hold_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_PRESSED) {
        unsaved_hold_tick = lv_tick_get();
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        if (unsaved_hold_tick) {
            unsaved_start_tick += lv_tick_elaps(unsaved_hold_tick);
            unsaved_hold_tick = 0;
        }
    }
}

static void unsaved_modal_close(void) {
    if (unsaved_modal_bg) lv_obj_add_flag(unsaved_modal_bg, LV_OBJ_FLAG_HIDDEN);
    if (unsaved_bar) lv_bar_set_value(unsaved_bar, 0, LV_ANIM_OFF);
    unsaved_start_tick = 0;
    unsaved_hold_tick = 0;
}

static void unsaved_confirm_cb(lv_event_t *e) {
    if (e && lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    unsaved_modal_close();
    int target = unsaved_target_screen_id;
    if (unsaved_source_screen_id == SCREEN_ID_SCREEN_SETTING_GENERAL) {
        lv_event_t ev;
        memset(&ev, 0, sizeof(ev));
        action_setting_general_save_button(&ev);
        sg18_speaker      = get_var_setting_general_speaker();
        sg18_auto_start   = get_var_setting_general_automatic_start();
        sg18_final_jack   = get_var_setting_general_final_jack();
        sg18_temp_limit   = get_var_setting_general_temperature_limit();
        sg18_pid          = get_var_setting_general_pid();
        sg18_tree_pedal   = get_var_setting_general_pedal_number3();
        sg18_wifi         = get_var_setting_general_wifi();
        sg18_orig_lang    = get_var_lang();
        sg18_lang         = get_var_lang();
        sg18_temp_caliber = get_var_setting_general_temperature_caliber();
        sg18_saved        = true;
        if (objects.obj37) lv_obj_set_style_bg_color(objects.obj37, lv_color_hex(0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (unsaved_source_screen_id == SCREEN_ID_SCREEN_SETTING_ADMIN) {
        lv_event_t ev;
        memset(&ev, 0, sizeof(ev));
        action_setting_admin_save_btn(&ev);
        sa_snap_tc_j  = get_var_setting_admin_thermocouple_j();
        sa_snap_emerg = get_var_setting_admin_emergency_switch();
        sa_snap_sensor = get_var_setting_admin_jack_sensor();
        sa_snap_days  = admin_countdown_draft_days();
        if (objects.obj77) lv_obj_set_style_bg_color(objects.obj77, lv_color_hex(0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    show_ui_toast(get_ui_saved_text());
    if (target > 0) eez_flow_set_screen(target, LV_SCR_LOAD_ANIM_NONE, 0, 0);
}

static void unsaved_cancel_cb(lv_event_t *e) {
    if (e && lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    unsaved_modal_close();
    int target = unsaved_target_screen_id;
    if (unsaved_source_screen_id == SCREEN_ID_SCREEN_SETTING_GENERAL) {
        set_var_setting_general_speaker(sg18_speaker);
        set_var_setting_general_automatic_start(sg18_auto_start);
        set_var_setting_general_final_jack(sg18_final_jack);
        set_var_setting_general_temperature_limit(sg18_temp_limit);
        set_var_setting_general_pid(sg18_pid);
        set_var_setting_general_pedal_number3(sg18_tree_pedal);
        set_var_setting_general_pedal_number2(!sg18_tree_pedal);
        set_var_setting_general_wifi(sg18_wifi);
        set_var_setting_general_temperature_caliber(sg18_temp_caliber);
        if (get_var_lang() != sg18_orig_lang) {
            apply_language_now(sg18_orig_lang);
        }
        sg18_saved = false;
        if (objects.obj37) lv_obj_set_style_bg_color(objects.obj37, lv_color_hex(0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
    } else if (unsaved_source_screen_id == SCREEN_ID_SCREEN_SETTING_ADMIN) {
        set_var_setting_admin_thermocouple_j(sa_snap_tc_j);
        set_var_setting_admin_thermocouple_k(!sa_snap_tc_j);
        set_var_setting_admin_emergency_switch(sa_snap_emerg);
        set_var_setting_admin_jack_sensor(sa_snap_sensor);
        set_var_setting_admin_password_placeholder("");
        set_var_setting_admin_re_enter_password_placeholder("");
        if (objects.obj77) lv_obj_set_style_bg_color(objects.obj77, lv_color_hex(0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    if (target > 0) eez_flow_set_screen(target, LV_SCR_LOAD_ANIM_NONE, 0, 0);
}

