        lv_obj_set_style_text_align(title, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_font(title, &ui_font_kalameh_bold_18, LV_PART_MAIN | LV_STATE_DEFAULT);
