        lv_obj_set_style_text_font(msg, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(msg, lv_color_hex(0xff333333), LV_PART_MAIN | LV_STATE_DEFAULT);

        lv_obj_t *ok_btn = lv_btn_create(card);
        lv_obj_set_pos(ok_btn, 16, 126);
        lv_obj_set_size(ok_btn, 136, 36);
        lv_obj_set_style_bg_color(ok_btn, lv_color_hex(0xff1a4880), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_radius(ok_btn, 7, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_add_event_cb(ok_btn, unsaved_confirm_cb, LV_EVENT_CLICKED, NULL);
