static void sg_frame_count_long_press_cb(lv_event_t *e) {
    // نگه‌داشتن ۲ ثانیه روی عدد چهارچوب → بوق + صفر شدن شمارنده
    static uint32_t fc_press_start = 0;
    static bool fc_done = false;
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_PRESSED) {
        fc_press_start = lv_tick_get();
        fc_done = false;
    } else if (code == LV_EVENT_PRESSING) {
        if (!fc_done && fc_press_start && lv_tick_elaps(fc_press_start) >= 2000) {
            fc_done = true;
            set_var_frame_numbers(0);
            if (buzzerTaskHandle) {
                xTaskNotify(buzzerTaskHandle, 1, eSetValueWithOverwrite);
            }
        }
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        fc_press_start = 0;
        fc_done = false;
    }
}

