static const char *get_sg_help_wifi_desc() { return get_ui_language_index() == 2 ? "Web uygulamasi icin WiFi" : (get_ui_language_index() == 1 ? "WiFi on/off for web app" : "روشن/خاموش وای‌فای وب‌اپ"); }
static const char *get_sg_help_title() { return get_ui_language_index() == 2 ? "Rehber" : (get_ui_language_index() == 1 ? "Guide" : "راهنما"); }

// افزودن یک آیتم در لیست راهنما: عنوان درشت‌تر و برجسته + توضیح در جلوی آن با سایز اصلی
static lv_obj_t *sg_help_add_item(lv_obj_t *list, const char *title, const char *desc) {
    int fa = (get_ui_language_index() == 0);
    lv_obj_t *cont = lv_obj_create(list);
    lv_obj_set_width(cont, LV_PCT(100));
    lv_obj_set_height(cont, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(cont, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(cont, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_all(cont, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_column(cont, 4, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(cont, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(cont, LV_OPA_TRANSP, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_clear_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_base_dir(cont, fa ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);

    lv_obj_t *lbl_title = lv_label_create(cont);
    lv_obj_set_style_text_font(lbl_title, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_color(lbl_title, lv_color_hex(0xff14304a), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_base_dir(lbl_title, fa ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
    char tbuf[128];
    snprintf(tbuf, sizeof(tbuf), "%s: ", title ? title : "");
    lv_label_set_text(lbl_title, tbuf);

    lv_obj_t *lbl_desc = lv_label_create(cont);
    lv_obj_set_flex_grow(lbl_desc, 1);
    lv_label_set_long_mode(lbl_desc, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_text_font(lbl_desc, &ui_font_kalameh_regular_12, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_color(lbl_desc, lv_color_hex(0xff14304a), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_base_dir(lbl_desc, fa ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_align(lbl_desc, fa ? LV_TEXT_ALIGN_RIGHT : LV_TEXT_ALIGN_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_text_line_space(lbl_desc, -3, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(lbl_desc, desc ? desc : "");

    return cont;
}

