static void jack_help_rebuild_content() {
    if (!jack_help_desc_lbl) return;
    bool fa = (get_ui_language_index() == 0);
    lv_obj_clean(jack_help_desc_lbl);
    static char _jh[2048];
    strncpy(_jh, get_help_jack_desc(), sizeof(_jh) - 1);
    _jh[sizeof(_jh) - 1] = 0;
    char *save = NULL;
    char *line = strtok_r(_jh, "\n", &save);
    while (line) {
        char *colon = strchr(line, ':');
        char prefix[24] = "";
        const char *body = line;
        if (colon) {
            int n = (int)(colon - line) + 1;
            if (n > (int)sizeof(prefix) - 1) n = sizeof(prefix) - 1;
            memcpy(prefix, line, n); prefix[n] = 0;
            body = colon + 1;
            while (*body == ' ') body++;
        }
        lv_obj_t *row = lv_obj_create(jack_help_desc_lbl);
        lv_obj_remove_style_all(row);
        lv_obj_set_width(row, LV_PCT(100));
        lv_obj_set_height(row, LV_SIZE_CONTENT);
        lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, fa ? LV_FLEX_ALIGN_END : LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
        lv_obj_set_style_base_dir(row, fa ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_pad_column(row, 4, LV_PART_MAIN | LV_STATE_DEFAULT);
        if (prefix[0]) {
            lv_obj_t *p = lv_label_create(row);
            lv_obj_set_style_text_font(p, &ui_font_kalameh_regular_12, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_text_color(p, lv_color_hex(0xff000000), LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_label_set_text(p, prefix);
        }
        lv_obj_t *b = lv_label_create(row);
        lv_obj_set_flex_grow(b, 1);
        lv_label_set_long_mode(b, LV_LABEL_LONG_WRAP);
        lv_obj_set_style_text_font(b, &ui_font_kalameh_regular_12, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(b, lv_color_hex(0xff9aa3ab), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(b, fa ? LV_TEXT_ALIGN_RIGHT : LV_TEXT_ALIGN_LEFT, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_line_space(b, -5, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_text(b, body);
        line = strtok_r(NULL, "\n", &save);
    }
}
