static void jack_capture_edit_snapshot(void) {
    const char *open_txt = objects.jack_bargasht_holder ? lv_textarea_get_text(objects.jack_bargasht_holder) : "0";
    const char *close_txt = objects.jack_raft_holder ? lv_textarea_get_text(objects.jack_raft_holder) : "0";
    jack_edit_start_open_ms = (int)(atof(open_txt ? open_txt : "0") * 1000.0f + 0.5f);
    jack_edit_start_close_ms = (int)(atof(close_txt ? close_txt : "0") * 1000.0f + 0.5f);
}

static int jack_ta_ms(lv_obj_t *ta) {
    bool valid = false;
    int32_t ms = jack_parse_text_ms(ta ? lv_textarea_get_text(ta) : "", jack_is_reinforce_mode, &valid);
    return valid ? (int)ms : 0;
}

