static void jack_clean_numeric_buf(char *buf, size_t cap) {
    if (!buf || cap == 0) return;
    char out[5] = {0};
    size_t j = 0;
    bool dot_seen = false;
    for (size_t i = 0; buf[i] && j + 1 < sizeof(out) && j + 1 < cap; i++) {
        char c = buf[i];
        if (c >= '0' && c <= '9') {
            out[j++] = c;
        } else if (c == '.' && !dot_seen) {
            out[j++] = c;
            dot_seen = true;
        }
    }
    out[j] = '\0';
    strncpy(buf, out, cap - 1);
    buf[cap - 1] = '\0';
}

static void jack_clean_integer_buf(char *buf, size_t cap) {
    if (!buf || cap == 0) return;
    char out[5] = {0};
    size_t j = 0;
    for (size_t i = 0; buf[i] && j + 1 < sizeof(out) && j + 1 < cap; i++) {
        char c = buf[i];
        if (c >= '0' && c <= '9') out[j++] = c;
    }
    out[j] = '\0';
    strncpy(buf, out, cap - 1);
    buf[cap - 1] = '\0';
}

static void event_handler_cb_screen_setting_jack_setting_jack_keyboard(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    // کیبورد جک فقط با handler خودمان عدد می‌نویسد؛ handler داخلی LVGL نباید متن/سمبل وارد کند.
    if (objects.jack_keyboard) lv_keyboard_set_textarea(objects.jack_keyboard, NULL);
    // هر لمس را فقط یک‌بار پردازش کن: فلگ با پایان لمس (RELEASED/PRESS_LOST) ریست می‌شود،
    // پس حتی اگر VALUE_CHANGED دوبار شلیک شود، رقم دوبار وارد نمی‌شود.
    static bool jk_consumed = false;
    if (event == LV_EVENT_RELEASED || event == LV_EVENT_PRESS_LOST) {
        jk_consumed = false;
        return;
    }
    if (event == LV_EVENT_VALUE_CHANGED) {
        if (jk_consumed) return;
        jk_consumed = true;
        lv_obj_t *kb = lv_event_get_target(e);
        uint16_t id = lv_btnmatrix_get_selected_btn(kb);
        const char *txt = lv_btnmatrix_get_btn_text(kb, id);
        lv_obj_t *ta = jack_active_ta;
        if (!txt || !ta) return;
        jack_touch_beep();
        if (strcmp(txt, "تایید") == 0 || strcmp(txt, "OK") == 0 || strcmp(txt, "Tamam") == 0) {
            if (!commit_both_jack_times(flowState, true)) return;
            e->user_data = (void *)0;
            action_jack_value_set(e);
            flowPropagateValueLVGLEvent(flowState, 52, 0, e);
            jack_active_ta = NULL;
            if (objects.panle_jack_modify) lv_obj_add_flag(objects.panle_jack_modify, LV_OBJ_FLAG_HIDDEN);
            return;
        }
        char buf[5];
        const char *cur = lv_textarea_get_text(ta);
        if (jack_replace_all_ta == ta) {
            buf[0] = '\0';
            jack_replace_all_ta = NULL;
        } else {
            strncpy(buf, cur ? cur : "", sizeof(buf) - 1);
            buf[sizeof(buf) - 1] = '\0';
        }
        if (jack_is_reinforce_mode) jack_clean_integer_buf(buf, sizeof(buf));
        else jack_clean_numeric_buf(buf, sizeof(buf));
        bool is_delete_key = (strcmp(txt, "پاک") == 0 || strcmp(txt, "C") == 0 ||
                              strcmp(txt, "پاک کردن") == 0 || strcmp(txt, "Del") == 0 || strcmp(txt, "Sil") == 0 ||
                              strstr(txt, "Del") != NULL || strstr(txt, "Sil") != NULL || strstr(txt, "پاک") != NULL ||
                              id == (jack_is_reinforce_mode ? 9U : 12U));
        if (is_delete_key) {
            size_t len = strlen(buf);
            if (len > 0) buf[len - 1] = '\0';
            jack_replace_all_ta = NULL;
        } else {
            if (!(txt[1] == '\0' && txt[0] >= '0' && txt[0] <= '9')) return;
            if (!jack_is_reinforce_mode && txt[0] == '.' && strchr(buf, '.')) return;
            if (strlen(buf) >= (jack_is_reinforce_mode ? 3U : 3U)) return;
            strncat(buf, txt, sizeof(buf) - strlen(buf) - 1);
        }
        tick_value_change_obj = ta;
        lv_textarea_set_text(ta, buf);
        tick_value_change_obj = NULL;

    }
}

static void event_handler_cb_screen_setting_jack_setting_jack_bargasht_holder(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    if (event == LV_EVENT_VALUE_CHANGED) {
        lv_obj_t *ta = lv_event_get_target(e);
        if (tick_value_change_obj != ta) {
            if (jack_replace_all_ta == ta) {
                const char *value = lv_textarea_get_text(ta);
                size_t len = strlen(value);
                char last[2] = { len ? value[len - 1] : '\0', '\0' };
                tick_value_change_obj = ta;
                lv_textarea_set_text(ta, last);
                tick_value_change_obj = NULL;
                jack_replace_all_ta = NULL;
            }
            commit_jack_time_from_ta(flowState, ta, 53, false);
        }
    }
    if (event == LV_EVENT_CLICKED || event == LV_EVENT_FOCUSED) {
        select_all_jack_time(objects.jack_bargasht_holder);
        e->user_data = (void *)0;
        flowPropagateValueLVGLEvent(flowState, 53, 0, e);
    }
}

