static void event_handler_cb_screen_setting_jack_setting_obj66(lv_event_t *e) {
    if (lv_event_get_code(e) == LV_EVENT_CLICKED) {
        void *flowState = lv_event_get_user_data(e);
        if (!commit_both_jack_times(flowState, true)) return;
        bool changed = (jack_ta_ms(objects.jack_bargasht_holder) != jack_edit_start_open_ms) ||
                       (jack_ta_ms(objects.jack_raft_holder) != jack_edit_start_close_ms);
        // آیتم بوق: فقط وقتی واقعاً ذخیره شد ۳ بوقِ کوتاه؛ اگر تغییری نبود همان ۲ بوقِ معمولی
        if (changed) xTaskNotify(buzzerTaskHandle, 5, eSetValueWithOverwrite);
        else jack_touch_beep();
        action_jack_value_set(e);
        show_ui_toast(changed ? get_ui_saved_text() : get_ui_no_change_text());
        jack_active_ta = NULL;
        if (objects.panle_jack_modify) lv_obj_add_flag(objects.panle_jack_modify, LV_OBJ_FLAG_HIDDEN);
    }
}
