static lv_obj_t *ui_toast_label = NULL;
static lv_timer_t *ui_toast_timer = NULL;
static uint32_t ui_toast_deadline = 0;
static uint32_t ui_toast_hold_tick = 0;

static void ui_toast_timer_tick_cb(lv_timer_t *timer) {
    (void)timer;
    if (!ui_toast_label || !lv_obj_is_valid(ui_toast_label) || lv_obj_has_flag(ui_toast_label, LV_OBJ_FLAG_HIDDEN)) {
        if (ui_toast_timer) {
            lv_timer_del(ui_toast_timer);
            ui_toast_timer = NULL;
        }
        return;
    }
    if (ui_toast_hold_tick != 0) {
        // حین لمس: زمان فریز است؛ ددلاین با گذشت زمان شیفت می‌یابد تا زمان باقیمانده حفظ شود
        uint32_t now = millis();
        ui_toast_deadline += (now - ui_toast_hold_tick);
        ui_toast_hold_tick = now;
        return;
    }
    if ((long)millis() - (long)ui_toast_deadline >= 0) {
        lv_obj_add_flag(ui_toast_label, LV_OBJ_FLAG_HIDDEN);
        if (ui_toast_timer) {
            lv_timer_del(ui_toast_timer);
            ui_toast_timer = NULL;
        }
    }
}

static void ui_toast_hold_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_PRESSED) {
        ui_toast_hold_tick = millis();
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        if (ui_toast_hold_tick != 0) {
            uint32_t now = millis();
            ui_toast_deadline += (now - ui_toast_hold_tick);
            ui_toast_hold_tick = 0;
        }
    }
}

static lv_obj_t *get_ui_toast_label(uint32_t color) {
    if (!ui_toast_label || !lv_obj_is_valid(ui_toast_label)) {
        ui_toast_label = lv_label_create(lv_layer_top());
        lv_obj_set_style_bg_opa(ui_toast_label, 235, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_toast_label, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_font(ui_toast_label, &ui_font_kalameh_bold_18, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_pad_all(ui_toast_label, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_radius(ui_toast_label, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(ui_toast_label, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_clear_flag(ui_toast_label, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_add_flag(ui_toast_label, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(ui_toast_label, ui_toast_hold_cb, LV_EVENT_ALL, NULL);
    }
    lv_obj_set_style_bg_color(ui_toast_label, lv_color_hex(color), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_base_dir(ui_toast_label, (get_ui_language_index() == 0) ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
    return ui_toast_label;
}

static void show_ui_toast_colored(const char *txt, uint32_t color, uint32_t ms) {
    lv_obj_t *t = get_ui_toast_label(color);
    if (ui_toast_timer) {
        lv_timer_del(ui_toast_timer);
        ui_toast_timer = NULL;
    }
    ui_toast_hold_tick = 0;
    ui_toast_deadline = millis() + ms;
    lv_obj_clear_flag(t, LV_OBJ_FLAG_HIDDEN);
    set_label_if_changed(t, txt);
    lv_obj_align(t, LV_ALIGN_CENTER, 0, -40);
    lv_obj_move_foreground(t);
    ui_toast_timer = lv_timer_create(ui_toast_timer_tick_cb, 50, NULL);
}

static char g_ui_toast_pending_msg[192] = { 0 };
static uint32_t g_ui_toast_pending_color = 0;
static uint32_t g_ui_toast_pending_ms = 0;
static volatile bool g_ui_toast_pending = false;

void ui_request_toast_colored(const char *msg, uint32_t color, uint32_t ms) {
    if (!msg || !msg[0]) return;
    strncpy(g_ui_toast_pending_msg, msg, sizeof(g_ui_toast_pending_msg) - 1);
    g_ui_toast_pending_msg[sizeof(g_ui_toast_pending_msg) - 1] = '\0';
    g_ui_toast_pending_color = color;
    g_ui_toast_pending_ms = ms;
    g_ui_toast_pending = true;
}

void check_ui_requested_toast(void) {
    if (g_ui_toast_pending) {
        g_ui_toast_pending = false;
        show_ui_toast_colored(g_ui_toast_pending_msg, g_ui_toast_pending_color, g_ui_toast_pending_ms);
    }
}

