static lv_obj_t  *pass_err_panel = NULL;
static lv_obj_t  *pass_err_bar = NULL;
static lv_timer_t *pass_err_timer = NULL;
static void pass_err_bar_anim_cb(void *bar, int32_t v) { lv_bar_set_value((lv_obj_t *)bar, v, LV_ANIM_OFF); }
typedef struct {
    lv_obj_t **bar;
    lv_timer_t **timer;
    bool paused;
    int32_t current;
    uint32_t remain_ms;
} pass_err_hold_t;
static pass_err_hold_t pass_err_hold = { &pass_err_bar, &pass_err_timer, false, 100, 6000 };
static void pass_err_close(void) {
    if (pass_err_timer) { lv_timer_del(pass_err_timer); pass_err_timer = NULL; }
    if (pass_err_panel) { lv_obj_del(pass_err_panel); pass_err_panel = NULL; pass_err_bar = NULL; }
    pass_err_hold.paused = false;
}
static void pass_err_timeout_cb(lv_timer_t *t) { (void)t; pass_err_timer = NULL; pass_err_close(); } // اتوبستن ۶ث
static void pass_err_close_cb(lv_event_t *e) { if (lv_event_get_code(e) == LV_EVENT_CLICKED) { jack_touch_beep(); pass_err_close(); } }
static void pass_err_hold_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (!pass_err_bar || !pass_err_timer) return;
    if (code == LV_EVENT_PRESSED) {
        lv_anim_t *a = lv_anim_get(pass_err_bar, pass_err_bar_anim_cb);
        if (a) {
            pass_err_hold.current = a->current_value;
            pass_err_hold.remain_ms = (uint32_t)((uint64_t)pass_err_hold.current * 6000U / 100U);
            if (pass_err_hold.remain_ms < 40) pass_err_hold.remain_ms = 40;
            lv_anim_del(pass_err_bar, pass_err_bar_anim_cb);
        }
        lv_timer_pause(pass_err_timer);
        pass_err_hold.paused = true;
    } else if ((code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) && pass_err_hold.paused) {
        pass_err_hold.paused = false;
        lv_timer_set_period(pass_err_timer, pass_err_hold.remain_ms);
        lv_timer_reset(pass_err_timer);
        lv_timer_resume(pass_err_timer);
        lv_anim_t a; lv_anim_init(&a);
        lv_anim_set_var(&a, pass_err_bar);
        lv_anim_set_exec_cb(&a, pass_err_bar_anim_cb);
        lv_anim_set_values(&a, pass_err_hold.current, 0);
        lv_anim_set_time(&a, pass_err_hold.remain_ms);
        lv_anim_start(&a);
    }
}
static void show_pass_error_dialog(const char *msg) {
    pass_err_close(); // اگر دیالوگِ قبلی باز است ببند
    pass_err_hold.current = 100;
    pass_err_hold.remain_ms = 6000;
    pass_err_hold.paused = false;
    lv_obj_t *p = lv_obj_create(lv_layer_top());
    pass_err_panel = p;
    lv_obj_set_size(p, 320, 150);
    lv_obj_align(p, LV_ALIGN_CENTER, 0, 0);
    lv_obj_clear_flag(p, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_event_cb(p, pass_err_hold_cb, LV_EVENT_ALL, NULL);
    lv_obj_set_style_bg_color(p, lv_color_hex(0xff2b2b2b), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(p, 250, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(p, 10, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(p, 2, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_color(p, lv_color_hex(0xffda8500), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(p, 10, LV_PART_MAIN | LV_STATE_DEFAULT);
    // دکمهٔ × گوشهٔ بالا
    lv_obj_t *x = lv_btn_create(p);
    lv_obj_set_size(x, 34, 34);
    lv_obj_align(x, LV_ALIGN_TOP_RIGHT, 4, -4);
    lv_obj_set_style_bg_color(x, lv_color_hex(0xffc0392b), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(x, 6, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(x, pass_err_close_cb, LV_EVENT_CLICKED, NULL);
    {
        lv_obj_t *xl = lv_label_create(x);
        lv_obj_set_style_text_font(xl, &lv_font_montserrat_14, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(xl, lv_color_white(), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_text(xl, LV_SYMBOL_CLOSE);
        lv_obj_center(xl);
    }
    // متنِ خطا (می‌تواند چندخطی باشد)
    {
        lv_obj_t *m = lv_label_create(p);
        lv_obj_add_flag(m, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(m, pass_err_hold_cb, LV_EVENT_ALL, NULL);
        lv_obj_set_width(m, 290);
        lv_obj_align(m, LV_ALIGN_CENTER, 0, 4);
        lv_obj_set_style_text_font(m, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(m, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_align(m, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_base_dir(m, (get_ui_language_index() == 0) ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_long_mode(m, LV_LABEL_LONG_WRAP);
        lv_label_set_text(m, msg);
    }
    // نوارِ خالی‌شونده (۱۰۰→۰ در ۶ ثانیه)
    {
        lv_obj_t *b = lv_bar_create(p);
        pass_err_bar = b;
        lv_obj_set_size(b, 290, 8);
        lv_obj_align(b, LV_ALIGN_BOTTOM_MID, 0, 0);
        lv_bar_set_range(b, 0, 100);
        lv_bar_set_value(b, 100, LV_ANIM_OFF);
        lv_obj_set_style_bg_color(b, lv_color_hex(0xff555555), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_color(b, lv_color_hex(0xffda8500), LV_PART_INDICATOR | LV_STATE_DEFAULT);
        lv_anim_t a; lv_anim_init(&a);
        lv_anim_set_var(&a, b);
        lv_anim_set_exec_cb(&a, pass_err_bar_anim_cb);
        lv_anim_set_values(&a, 100, 0);
        lv_anim_set_time(&a, 6000);
        lv_anim_start(&a);
    }
    lv_obj_move_foreground(p);
    pass_err_timer = lv_timer_create(pass_err_timeout_cb, 6000, NULL);
    lv_timer_set_repeat_count(pass_err_timer, 1);
}

// زمانِ ورود به صفحه‌ی تنظیمات مدیر — برای نادیده‌گرفتنِ لمسِ ادامه‌دار از صفحه‌ی رمز
static uint32_t admin_settings_load_tick = 0;

static void event_handler_cb_screen_setting_admin_screen_setting_admin(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;

    if (event == LV_EVENT_SCREEN_LOAD_START) {
        // group: jjj
        lv_group_remove_all_objs(groups.jjj);
        admin_settings_load_tick = lv_tick_get();
        sa_load_tick = lv_tick_get();
        s_sa_last_tick = 0;
        admin_rtc_panel_open();
        sa_snap_tc_j  = get_var_setting_admin_thermocouple_j();
        sa_snap_emerg = get_var_setting_admin_emergency_switch();
        sa_snap_sensor = get_var_setting_admin_jack_sensor();
        sa_snap_days  = admin_countdown_draft_days();
        if (objects.obj77) lv_obj_set_style_bg_color(objects.obj77, lv_color_hex(0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
        // ایمنیِ اضافه: setting_admin_pass_change_panle دقیقاً رویِ کل کادرِ محتوا (0,0, 361x320)
        // می‌نشیند و فقط نوارِ کناری را باز می‌گذارد — همان چیزی که وقتی «باز» گیر می‌کند، دیده
        // می‌شود (کادرِ محتوا خالی، نوارِ کناری سالم). هر بار که این صفحه (از هر مسیری، از جمله
        // اطلاعات→مدیر) بارگذاری می‌شود، این پنل و راهنما اجباراً بسته می‌شوند تا محتوای اصلی
        // همیشه دیده شود، صرف‌نظر از این‌که چرا/کجا باز مانده بود.
        if (objects.setting_admin_pass_change_panle) lv_obj_add_flag(objects.setting_admin_pass_change_panle, LV_OBJ_FLAG_HIDDEN);
        if (sa_help_panel) lv_obj_add_flag(sa_help_panel, LV_OBJ_FLAG_HIDDEN);
    }
    if (event == LV_EVENT_SCREEN_LOADED) {
        admin_settings_load_tick = lv_tick_get();
        sa_load_tick = lv_tick_get();
        e->user_data = (void *)0;
        flowPropagateValueLVGLEvent(flowState, 1, 0, e);
    }
}

