static void event_handler_cb_screen_setting_admin_obj77(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_CLICKED) {
        // محافظ: تا ۹۰۰ms بعد از ورود به صفحه، کلیکِ ناشی از «لمسِ ادامه‌دارِ» تاییدِ رمز را نادیده بگیر
        // تا ذخیره به‌اشتباه نخورد. کاربر باید دست بردارد و دوباره بزند.
        if ((uint32_t)(lv_tick_get() - admin_settings_load_tick) < 900U) {
            return;
        }
        // آیتم بوق: دیگر همان اولِ کلیک بوقِ عمومی نمی‌زند — بسته به نتیجه (خطا/ذخیرهٔ موفق) پایین‌تر
        // بوقِ مناسب (۲ بوقِ بلند برایِ خطا، ۳ بوقِ کوتاه برایِ ذخیرهٔ موفق) زده می‌شود.
        // اعتبارسنجی رمز قبل از ذخیره — اگر مشکل داشت، دیالوگ خطا و توقفِ ذخیره
        {
            const char *adPass = get_var_setting_admin_password_placeholder();
            const char *adRe = get_var_setting_admin_re_enter_password_placeholder();
            if (!adPass) adPass = "";
            if (!adRe) adRe = "";
            if (adPass[0] != '\0') {
                char err[200];
                err[0] = '\0';
                if (strlen(adPass) < 4) {
                    strncat(err, get_pass_err_minlen(), sizeof(err) - strlen(err) - 1);
                }
                if (adRe[0] == '\0') {
                    if (err[0]) strncat(err, "\n", sizeof(err) - strlen(err) - 1);
                    strncat(err, get_pass_err_norepeat(), sizeof(err) - strlen(err) - 1);
                } else if (strcmp(adPass, adRe) != 0) {
                    if (err[0]) strncat(err, "\n", sizeof(err) - strlen(err) - 1);
                    strncat(err, get_pass_err_mismatch(), sizeof(err) - strlen(err) - 1);
                }
                if (err[0]) {
                    set_var_setting_admin_pass_error(""); // ارورِ اینلاینِ قدیمی نمایش داده نشود
                    xTaskNotify(buzzerTaskHandle, 3, eSetValueWithOverwrite); // خطا = ۲ بوقِ بلند
                    show_pass_error_dialog(err);
                    return;
                }
            }
        }
        if (admin_rtc_time_user_edited()) {
            set_var_admin_set_hour(parse_dropdown_number(admin_time_hour_dropdown, get_var_admin_set_hour()));
            set_var_admin_set_minute(parse_dropdown_number(admin_time_minute_dropdown, get_var_admin_set_minute()));
        }
        if (admin_rtc_date_user_edited()) {
            set_var_admin_set_year(parse_dropdown_number(admin_date_year_dropdown, get_var_admin_set_year()));
            set_var_admin_set_month(parse_dropdown_number(admin_date_month_dropdown, get_var_admin_set_month()));
            set_var_admin_set_day(parse_dropdown_number(admin_date_day_dropdown, get_var_admin_set_day()));
        }
        e->user_data = (void *)0;
        action_setting_admin_save_btn(e);
        sa_snap_tc_j  = get_var_setting_admin_thermocouple_j();
        sa_snap_emerg = get_var_setting_admin_emergency_switch();
        sa_snap_sensor = get_var_setting_admin_jack_sensor();
        sa_snap_days  = admin_countdown_draft_days();
        if (objects.obj77) lv_obj_set_style_bg_color(objects.obj77, lv_color_hex(0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
        xTaskNotify(buzzerTaskHandle, 5, eSetValueWithOverwrite); // ذخیرهٔ موفق = ۳ بوقِ کوتاه
        show_ui_toast(get_ui_saved_text());
        // پس از ذخیره از منو خارج نشود؛ روی همان صفحهٔ تنظیمات مدیر بماند.
        // (ناوبریِ flowPropagateValueLVGLEvent(flowState, 35, ...) حذف شد)
    }
}

