// صفحهٔ رمز مدیر: هر دکمهٔ کناری مستقیم به صفحهٔ خودش برود (نه «برگشت» همگانی)
static void event_handler_cb_screen_admin_password_sidebar(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    int idx = (int)(intptr_t)lv_obj_get_user_data(lv_event_get_target(e));
    switch (idx) {
        case 0: eez_flow_set_screen(SCREEN_ID_SCREEN_SETTING_GENERAL,      LV_SCR_LOAD_ANIM_NONE, 0, 0); break;
        case 1: eez_flow_set_screen(SCREEN_ID_SCREEN_SETTING_JACK_SETTING, LV_SCR_LOAD_ANIM_NONE, 0, 0); break;
        case 3: eez_flow_set_screen(SCREEN_ID_SCREEN_UPDATE,               LV_SCR_LOAD_ANIM_NONE, 0, 0); break;
        case 4: eez_flow_set_screen(SCREEN_ID_SCREEN_MENU,                 LV_SCR_LOAD_ANIM_NONE, 0, 0); break;
        default: break; // idx 2 = مدیر: روی همین صفحهٔ رمز بماند
    }
}

