static const char *wifi_screen_status_text(void);
static const char *wifi_dropdown_options_text(void);
static void wifi_dropdown_apply_ltr_styles(lv_obj_t *dd);

// رفرش UI فقط از نخ LVGL؛ از تسک وای‌فای فقط این پرچم ست می‌شود (lv_async ناامن است)
static volatile bool g_wifi_ui_dirty = false;
static volatile bool g_wifi_request_show_password_panel = false;

void wifi_ui_request_password_panel(void) {
    g_wifi_request_show_password_panel = true;
    g_wifi_ui_dirty = true;
}

static void wifi_dropdown_force_close(void) {
    if (objects.drop_down_wifi_list && lv_dropdown_is_open(objects.drop_down_wifi_list))
        lv_dropdown_close(objects.drop_down_wifi_list);
}

static void wifi_ui_apply_now(void) {
    if (g_wifi_request_show_password_panel) {
        g_wifi_request_show_password_panel = false;
        if (eez_flow_get_current_screen() != SCREEN_ID_SCREEN_WIFI) {
            eez_flow_set_screen(SCREEN_ID_SCREEN_WIFI, LV_SCR_LOAD_ANIM_NONE, 0, 0);
        }
        extern void wifi_password_panel_show(void);
        wifi_password_panel_show();
    }
    if (!objects.drop_down_wifi_list) return;
    // هنگام باز بودنِ لیست، set_options نکن — لیست می‌رود گوشهٔ بالا-چپ + UAF روی buffer گزینه‌ها
    if (!lv_dropdown_is_open(objects.drop_down_wifi_list)) {
        const char *opts = wifi_dropdown_options_text();
        const char *cur = lv_dropdown_get_options(objects.drop_down_wifi_list);
        if (!cur) cur = "";
        if (!opts) opts = "";
        if (strcmp(cur, opts) != 0) {
            tick_value_change_obj = objects.drop_down_wifi_list;
            lv_dropdown_set_options(objects.drop_down_wifi_list, opts);
            wifi_dropdown_apply_ltr_styles(objects.drop_down_wifi_list);
            tick_value_change_obj = NULL;
        }
        int sel = get_var_selected_wifi_index();
        if (sel < 0) sel = 0;
        if ((int)lv_dropdown_get_selected(objects.drop_down_wifi_list) != sel) {
            tick_value_change_obj = objects.drop_down_wifi_list;
            lv_dropdown_set_selected(objects.drop_down_wifi_list, sel);
            tick_value_change_obj = NULL;
        }
    }
    if (objects.obj118) {
        const char *st = wifi_screen_status_text();
        lv_label_set_text(objects.obj118, (st && st[0]) ? st : "");
    }
    if (objects.obj112) {
        const char *net = get_var_selected_wifi_network();
        const char *cur = lv_label_get_text(objects.obj112);
        if (!net) net = "";
        if (!cur) cur = "";
        if (strcmp(cur, net) != 0) {
            tick_value_change_obj = objects.obj112;
            lv_label_set_text(objects.obj112, net);
            tick_value_change_obj = NULL;
        }
    }
    // textarea فقط از نخ LVGL — حین تایپ بازنویسی نکن
    bool editing = false;
    if (objects.text_area_wifi_password) {
        lv_state_t st = lv_obj_get_state(objects.text_area_wifi_password);
        if (st & (LV_STATE_FOCUSED | LV_STATE_EDITED)) editing = true;
    }
    if (objects.keybord && !lv_obj_has_flag(objects.keybord, LV_OBJ_FLAG_HIDDEN))
        editing = true;
    if (!editing && objects.text_area_wifi_password) {
        const char *pw = get_var_wifi_password();
        const char *cur = lv_textarea_get_text(objects.text_area_wifi_password);
        if (!pw) pw = "";
        if (!cur) cur = "";
        if (strcmp(cur, pw) != 0) {
            tick_value_change_obj = objects.text_area_wifi_password;
            lv_textarea_set_text(objects.text_area_wifi_password, pw);
            tick_value_change_obj = NULL;
        }
    }
}

void wifi_ui_request_refresh(void) {
    g_wifi_ui_dirty = true;
}

static bool wifi_list_has_networks(const char *src);

static void event_handler_cb_screen_wifi_screen_wifi(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_SCREEN_LOAD_START) {
        // group: jjj
        lv_group_remove_all_objs(groups.jjj);
        s_wifi_last_tick = 0;
        // لیستِ بازِ قبلی روی صفحهٔ زنده می‌ماند و گوشه بالا-چپ می‌چسبد — همیشه ببند
        wifi_dropdown_force_close();
        const char *cur = get_var_available_wifi_networks();
        extern bool self_update_is_task_alive(void);
        if (g_self_update_session || self_update_is_task_alive()) {
            self_update_ensure_task();
            wifi_ui_request_refresh();
        } else if (get_var_ota_enable()) {
            // ota_task ممکن است قبل از ورود به این صفحه اسکن کرده باشد — نتیجه را پاک نکن
            if (!wifi_list_has_networks(cur)) {
                g_wifi_ota_rescan_request = true;
                set_var_available_wifi_networks("SEARCHING");
            }
            wifi_ui_request_refresh();
        } else {
            set_var_available_wifi_networks("SEARCHING");
            wifi_ui_request_refresh();
            action_btn_wifi_search_event(NULL);
        }
    } else if (event == LV_EVENT_SCREEN_UNLOAD_START) {
        wifi_dropdown_force_close();
    }
}

static void event_handler_cb_screen_wifi_back(lv_event_t *e) {
    if (lv_event_get_code(e) == LV_EVENT_CLICKED) {
        jack_touch_beep();
        wifi_dropdown_force_close();
        // اگر از مسیرِ F5-بوت به اینجا رسیده‌ایم (ota_enable)، برگشت باید به منو باشد — آن مسیر اصلاً
        // از صفحهٔ اطلاعات رد نشده. در غیرِ این‌صورت (دکمهٔ «بروزرسانی» یا دکمهٔ «وای‌فای» — هردو از
        // صفحهٔ اطلاعات) باید دقیقاً به همان صفحهٔ اطلاعات برگردد، نه منو.
        bool wasOtaBoot = get_var_ota_enable();
        safe_return_from_ota_to_menu();
        eez_flow_set_screen(wasOtaBoot ? SCREEN_ID_SCREEN_MENU : SCREEN_ID_SCREEN_UPDATE, LV_SCR_LOAD_ANIM_NONE, 0, 0);
    }
}

static void event_handler_cb_screen_wifi_drop_down_wifi_list(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_VALUE_CHANGED) {
        lv_obj_t *ta = lv_event_get_target(e);
        if (tick_value_change_obj != ta) {
            int32_t value = lv_dropdown_get_selected(ta);
            if (flowState) {
                assignIntegerProperty(flowState, 3, 4, value, "Failed to assign Selected in Dropdown widget");
            }
            set_var_selected_wifi_index(value);
            wifi_on_dropdown_selection_changed(value);
            // شبکهٔ امنِ بدون رمز ذخیره‌شده → پنل ورود رمز (ترد LVGL)
            if (wifi_selected_needs_password())
                wifi_password_panel_show();
            else
                wifi_password_panel_hide();
        }
    }
}

static void event_handler_cb_screen_wifi_btn_wifi_connect(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_CLICKED) {
        jack_touch_beep();
        e->user_data = (void *)0;
        action_btn_connect(e);
        action_btn_wifi_connect_event(e);
    }
}

static void event_handler_cb_screen_wifi_btn_wifi_redresh(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_CLICKED) {
        jack_touch_beep();
        wifi_scan_spinner_set_visible(true);
        e->user_data = (void *)0;
        action_btn_wifi_search_event(e);
    }
}

static void event_handler_cb_screen_wifi_panle_wifi_password(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_SCREEN_LOADED) {
        e->user_data = (void *)0;
        flowPropagateValueLVGLEvent(flowState, 9, 0, e);
    }
}

static void event_handler_cb_screen_wifi_obj111(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_CLICKED) {
        jack_touch_beep();
        e->user_data = (void *)0;
        wifi_password_panel_hide();
        flowPropagateValueLVGLEvent(flowState, 10, 0, e);
    }
}

static void event_handler_cb_screen_wifi_keybord(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_READY) {
        e->user_data = (void *)0;
        action_btn_wifi_connect_event(e);
        flowPropagateValueLVGLEvent(flowState, 13, 0, e);
    } else if (event == LV_EVENT_VALUE_CHANGED) {
        lv_obj_t *kb = lv_event_get_target(e);
        uint32_t btn_id = lv_buttonmatrix_get_selected_button(kb);
        if (btn_id != LV_BUTTONMATRIX_BUTTON_NONE) {
            const char *txt = lv_buttonmatrix_get_button_text(kb, btn_id);
            if (txt && strcmp(txt, "Space") == 0 && objects.text_area_wifi_password) {
                const char *cur = lv_textarea_get_text(objects.text_area_wifi_password);
                size_t len = cur ? strlen(cur) : 0;
                if (len >= 5 && strcmp(cur + len - 5, "Space") == 0) {
                    for (int k = 0; k < 5; k++) lv_textarea_delete_char(objects.text_area_wifi_password);
                    lv_textarea_add_char(objects.text_area_wifi_password, ' ');
                }
            }
        }
    }
}

static void event_handler_cb_screen_wifi_text_area_wifi_password(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;
    
    if (event == LV_EVENT_VALUE_CHANGED) {
        lv_obj_t *ta = lv_event_get_target(e);
        if (tick_value_change_obj != ta) {
            const char *value = lv_textarea_get_text(ta);
            set_var_wifi_password(value ? value : "");
        }
    }
}

static void event_handler_cb_screen_wifi_language_panle(lv_event_t *e) {
    lv_event_code_t event = lv_event_get_code(e);
    void *flowState = lv_event_get_user_data(e);
    (void)flowState;

    if (event == LV_EVENT_CLICKED) {
        jack_touch_beep();
        int32_t lang = get_var_lang();
        if (lang < 1 || lang > 3) {
            lang = 1;
        }
        lang = (lang % 3) + 1;
        apply_language_now(lang);
    }
    
    if (event == LV_EVENT_PRESSED) {
        e->user_data = (void *)0;
        flowPropagateValueLVGLEvent(flowState, 19, 0, e);
    }
}

