void delete_screen_screen_splash() {
    lv_obj_del(objects.screen_splash);
    objects.screen_splash = 0;
    objects.obj0 = 0;
    objects.obj1 = 0;
    splash_esp_temp_label = NULL;
    splash_frame_cur_label = NULL;
    splash_days_label = NULL;
    splash_company_label = NULL;
    splash_version_line = NULL;
    splash_bg_img = NULL;
    deletePageFlowState(0);
}

void tick_screen_screen_splash() {
    void *flowState = getFlowState(0, 0);
    (void)flowState;

    extern bool g_is_crash_recovery_boot;
    static uint32_t splash_boot_start = 0;
    if (splash_boot_start == 0) splash_boot_start = lv_tick_get();
    uint32_t splash_wait = g_is_crash_recovery_boot ? 0U : 2000U;
    if (lv_tick_elaps(splash_boot_start) >= splash_wait && !company_setup_pending() && eez_flow_get_current_screen() == SCREEN_ID_SCREEN_SPLASH) {
        extern int16_t get_saved_active_screen(void);
        int16_t target_scr = get_saved_active_screen();
        if (target_scr < SCREEN_ID_SCREEN_MENU || target_scr > _SCREEN_ID_LAST || target_scr == SCREEN_ID_SCREEN_LOADING) {
            target_scr = SCREEN_ID_SCREEN_MENU;
        }
        // اگر دستگاه قفل است، فقط SCREEN_MENU مجاز است تا lock_overlay روی آن ساخته شود
        if (g_device_locked) target_scr = SCREEN_ID_SCREEN_MENU;
        eez_flow_set_screen(target_scr, LV_SCR_LOAD_ANIM_NONE, 0, 0);
        if (target_scr == SCREEN_ID_SCREEN_WIFI) {
            extern void start_info_self_update(void);
            start_info_self_update();
        }
    }

    static uint32_t splash_last_tick = 0;
    if (!g_force_language_refresh && splash_last_tick != 0 && lv_tick_elaps(splash_last_tick) < 200U) {
        return;
    }
    splash_last_tick = lv_tick_get();
    {
        char new_val[96];
        const char *sw = get_var_software_version();
        int splang = get_ui_language_index();
        if (g_lock_remaining_days > 0) {
            // فقط عدد کنارِ نسخه (بدونِ نوشتهٔ «روز مانده»)
            if (splang == 1) snprintf(new_val, sizeof(new_val), "Version: V.%s | %d", sw, g_lock_remaining_days);
            else if (splang == 2) snprintf(new_val, sizeof(new_val), "Versiyon: V.%s | %d", sw, g_lock_remaining_days);
            else snprintf(new_val, sizeof(new_val), "%d | V.%s  :نسخه کد", g_lock_remaining_days, sw);
        } else {
            if (splang == 1) snprintf(new_val, sizeof(new_val), "Version: V.%s", sw);
            else if (splang == 2) snprintf(new_val, sizeof(new_val), "Versiyon: V.%s", sw);
            else snprintf(new_val, sizeof(new_val), "V.%s  :نسخه کد", sw);
        }
        const char *cur_val = lv_label_get_text(objects.obj0);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj0;
            lv_label_set_text(objects.obj0, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        // آیتم ۱ — «چهارچوب کل» سمت راست — عدد زیرِ نوشته
        obj_set_x_if_changed(objects.obj1, get_ui_language_index() == 2 ? 115 : 150);
        char new_val[48];
        snprintf(new_val, sizeof(new_val), "%s\n%ld", get_ui_frame_total_prefix(), (long)get_var_total_frame_numbers());
        const char *cur_val = lv_label_get_text(objects.obj1);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj1;
            lv_label_set_text(objects.obj1, new_val);
            tick_value_change_obj = NULL;
        }
    }
    if (splash_bg_img) {
        // آیتم ۳: تا وقتی ثبت‌نامِ اولِ بوت (نام شرکت/رمز مدیر) تمام نشده، عکسِ لگو پنهان بماند
        // تا اولین چیزی که کاربر می‌بیند «صفحهٔ نام شرکت» باشد، نه عکسِ برج/شهر.
        if (company_setup_pending()) lv_obj_add_flag(splash_bg_img, LV_OBJ_FLAG_HIDDEN);
        else lv_obj_clear_flag(splash_bg_img, LV_OBJ_FLAG_HIDDEN);
    }
    if (splash_company_label) {
        // آیتم ۳ — نام شرکت روی صفحه لگو (عکس خام نوشته ندارد، پس همیشه نمایش داده می‌شود)
        const char *cn = company_display_name();
        size_t cn_len = cn ? strlen(cn) : 0;
        const lv_font_t *font = (cn_len >= 19) ? &lv_font_montserrat_20 : (cn_len >= 15 ? &lv_font_montserrat_24 : &lv_font_montserrat_28);
        lv_obj_set_style_text_font(splash_company_label, font, LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_label_set_long_mode(splash_company_label, LV_LABEL_LONG_CLIP);
        const char *cur = lv_label_get_text(splash_company_label);
        if (cn && strcmp(cur, cn) != 0) lv_label_set_text(splash_company_label, cn);
    }
    if (splash_frame_cur_label) {
        // آیتم ۱ — «چهارچوب» جاری سمت چپ — عدد زیرِ نوشته
        char new_val[48];
        snprintf(new_val, sizeof(new_val), "%s\n%ld", get_ui_frame_prefix(), (long)get_var_frame_numbers());
        const char *cur_val = lv_label_get_text(splash_frame_cur_label);
        if (strcmp(new_val, cur_val) != 0)
            lv_label_set_text(splash_frame_cur_label, new_val);
    }
    if (splash_days_label) {
        // روزهای باقی‌مانده از این نسخه به بعد کنارِ متن نسخه نمایش داده می‌شود، نه در خط جدا.
        lv_obj_add_flag(splash_days_label, LV_OBJ_FLAG_HIDDEN);
    }
    if (splash_esp_temp_label) {
        char new_val[32];
        {
            int splang2 = get_ui_language_index();
            const char *ct = get_var_cpu_temperature_text();
            if (splang2 == 1) snprintf(new_val, sizeof(new_val), "CPU Temp: %s", ct);
            else if (splang2 == 2) snprintf(new_val, sizeof(new_val), "CPU Isisi: %s", ct);
            else snprintf(new_val, sizeof(new_val), "دما cpu :  %s", ct);
        }
        const char *cur_val = lv_label_get_text(splash_esp_temp_label);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = splash_esp_temp_label;
            lv_label_set_text(splash_esp_temp_label, new_val);
            tick_value_change_obj = NULL;
        }
    }
}

