                                    lv_obj_set_pos(obj, 0, 12);
                                    lv_obj_set_size(obj, 340, LV_SIZE_CONTENT);
                                    lv_obj_set_style_text_font(obj, &ui_font_kalameh_bold_18, LV_PART_MAIN | LV_STATE_DEFAULT);
