// آیتم ۱۱ — ذخیره پیش‌فرض در صفحه مدیر
static const char *get_sa_default_confirm_msg(void) {
    return get_ui_language_index() == 2
        ? "Onaylarsaniz su anki tum ayarlar fabrika ayari olarak kaydedilir. Bundan sonra Genel Ayarlar'da fabrika sifirlama yapilinca cihaz bu degerlere doner."
        : (get_ui_language_index() == 1
            ? "If you confirm, all current device settings will be saved as the factory defaults. From now on, Factory Reset in General Settings restores these exact values."
            : "با تأیید، تمام تنظیمات فعلی دستگاه به عنوان تنظیمات کارخانه ذخیره می‌شود. از این به بعد هر بار در تنظیمات عمومی ریست فکتوری بزنید، دستگاه دقیقاً به همین مقادیر برمی‌گردد.");
}
static void sa_default_confirm_close(void) {
    if (sa_default_confirm_panel) lv_obj_add_flag(sa_default_confirm_panel, LV_OBJ_FLAG_HIDDEN);
    if (sa_default_bar) lv_bar_set_value(sa_default_bar, 0, LV_ANIM_OFF);
    sa_default_confirm_tick = 0;
    sa_default_confirm_hold_tick = 0;
}
static void sa_default_cancel_cb(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    sa_default_confirm_close();
}
static void sa_default_confirm_cb(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    sa_default_confirm_close();
    e->user_data = (void *)0;
    action_setting_admin_save_backup_values(e);
    show_ui_toast_blue(get_ui_saved_text()); // آبی تا با ذخیرهٔ سبزِ تنظیمات فرق کند
}
static void sa_default_hold_cb(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_PRESSED) {
        sa_default_confirm_hold_tick = lv_tick_get();
    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
        if (sa_default_confirm_hold_tick) {
            sa_default_confirm_tick += lv_tick_elaps(sa_default_confirm_hold_tick);
            sa_default_confirm_hold_tick = 0;
        }
    }
}
static void sa_default_confirm_open(void) {
    if (!sa_default_confirm_panel) return;
    int fa = (get_ui_language_index() == 0);
    if (sa_default_title_label) set_label_if_changed(sa_default_title_label, get_sa_save_default_text());
    if (sa_default_msg_label) {
        set_label_if_changed(sa_default_msg_label, get_sa_default_confirm_msg());
        lv_obj_set_style_base_dir(sa_default_msg_label, fa ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
    }
    if (sa_default_ok_label) set_label_if_changed(sa_default_ok_label, get_sg_confirm_text());
    if (sa_default_cancel_label) set_label_if_changed(sa_default_cancel_label, get_sg_cancel_text());

    sa_default_confirm_tick = lv_tick_get();
    sa_default_confirm_hold_tick = 0;
    if (sa_default_bar) lv_bar_set_value(sa_default_bar, 0, LV_ANIM_OFF);
    lv_obj_clear_flag(sa_default_confirm_panel, LV_OBJ_FLAG_HIDDEN);
    lv_obj_move_foreground(sa_default_confirm_panel);
}
static void sa_save_default_btn_cb(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    if ((uint32_t)(lv_tick_get() - admin_settings_load_tick) < 900U) return; // محافظِ لمسِ ادامه‌دار
    jack_touch_beep();
    sa_default_confirm_open();
}

static lv_obj_t *sa_countdown_slider = NULL; // نمودارِ افقیِ روزها (جایگزینِ +/-)

static void event_handler_sa_reverse_timer_toggle(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    admin_countdown_toggle();
}
static void event_handler_sa_reverse_timer_open_chain(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    if (multi_timer_dialog_can_open()) {
        multi_timer_dialog_open();
    } else {
        const char *msg = get_ui_language_index() == 2
            ? "Once T1 days are set, tap here again"
            : (get_ui_language_index() == 1 ? "Set T1 days first, then tap here" : "اول روزهای T1 را تنظیم کنید، سپس دوباره اینجا بزنید");
        show_ui_toast(msg);
    }
}

