void tick_screen_screen_setting_admin() {
    // دیالوگِ تمام‌صفحه‌ی تایمرهای T2-T5 روی این صفحه باز است → این صفحه کاملاً پوشیده و دیده
    // نمی‌شود؛ آپدیت‌کردنِ لیبل‌ها/چک‌باکس‌هاش هدررفتنِ محضِ CPU است، مخصوصاً وقتی کاربر همون لحظه
    // دارد اسلایدرِ دیالوگ را می‌کشد. تمام مقادیر بر پایه‌ی lv_tick_elaps (زمانِ واقعی) هستند، پس
    // با بستنِ دیالوگ همه‌چیز بدونِ drift خودش را همگام می‌کند.
    if (multi_timer_dialog_is_open()) return;
    void *flowState = getFlowState(0, 4);
    (void)flowState;
    bool sa_pass_panel_open = objects.setting_admin_pass_change_panle &&
        !lv_obj_has_flag(objects.setting_admin_pass_change_panle, LV_OBJ_FLAG_HIDDEN);
    bool sa_user_active = sa_pass_panel_open ||
        (objects.obj68 && lv_obj_has_state(objects.obj68, LV_STATE_PRESSED)) ||
        textarea_user_active(objects.obj73) ||
        textarea_user_active(objects.obj74) ||
        textarea_user_active(objects.change_value_admin_pass_1);
    bool sa_touch_active = is_ui_interaction_active();
    uint32_t sa_period = (sa_user_active || sa_touch_active) ? 20U : 80U;
    if (!g_force_language_refresh && s_sa_last_tick != 0 && lv_tick_elaps(s_sa_last_tick) < sa_period) {
        return;
    }
    s_sa_last_tick = lv_tick_get();
    if (objects.obj77) {
        static bool s_obj77_dirty_state = false;
        bool dirty = sa_is_dirty();
        if (dirty != s_obj77_dirty_state) {
            s_obj77_dirty_state = dirty;
            lv_obj_set_style_bg_color(objects.obj77, lv_color_hex(dirty ? 0xff1a73e8 : 0xff26bb50), LV_PART_MAIN | LV_STATE_DEFAULT);
        }
    }
    if (sa_default_confirm_panel && !lv_obj_has_flag(sa_default_confirm_panel, LV_OBJ_FLAG_HIDDEN) && sa_default_confirm_tick) {
        if (sa_default_confirm_hold_tick) {
            sa_default_confirm_tick += lv_tick_elaps(sa_default_confirm_hold_tick);
            sa_default_confirm_hold_tick = lv_tick_get();
        } else {
            uint32_t el = lv_tick_elaps(sa_default_confirm_tick);
            if (el >= 7000) {
                sa_default_confirm_close();
            } else if (sa_default_bar) {
                lv_bar_set_value(sa_default_bar, (int)(el * 100 / 7000), LV_ANIM_OFF);
            }
        }
    }
    int32_t sa_static_lang = get_ui_language_index();
    bool sa_static_due = (sa_static_lang != sa_static_last_lang) || g_force_language_refresh;
    if (sa_static_due) {
        sa_static_last_lang = sa_static_lang;
        // نوارِ کناریِ این صفحه هم مثلِ صفحهٔ زمان‌بندیِ جک‌ها قبلاً هندلِ سراسری نداشت و با تغییرِ
        // زبان به‌روز نمی‌شد.
        if (sa_tab_general_label) set_label_if_changed(sa_tab_general_label, get_sg_tab_general_text());
        if (sa_tab_jack_label)    set_label_if_changed(sa_tab_jack_label,    get_sg_tab_jack_text());
        if (sa_tab_admin_label)   set_label_if_changed(sa_tab_admin_label,   get_sg_tab_admin_text());
        if (sa_tab_help_label)    set_label_if_changed(sa_tab_help_label,    get_sg_tab_help_text());
        if (sa_tab_exit_label)    set_label_if_changed(sa_tab_exit_label,    get_sg_tab_exit_text());
        if (sa_help_btn_label)    set_label_if_changed(sa_help_btn_label,    get_sg_help_title());
        if (sa_help_title_label)  set_label_if_changed(sa_help_title_label,  get_sg_help_title());
        if (sa_thermocouple_label) set_label_if_changed(sa_thermocouple_label, get_sa_thermocouple_text());
        if (sa_emergency_mode_label) {
            set_label_if_changed(sa_emergency_mode_label, get_sa_emergency_mode_text());
            lv_obj_set_style_base_dir(sa_emergency_mode_label, (get_ui_language_index() == 0) ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        }
        if (sa_jack_sensor_label) {
            set_label_if_changed(sa_jack_sensor_label, get_sa_jack_sensor_text());
            lv_obj_set_style_base_dir(sa_jack_sensor_label, (get_ui_language_index() == 0) ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
        }
        if (sa_reverse_timer_label) set_label_if_changed(sa_reverse_timer_label, get_sa_reverse_timer_text());
        if (sa_change_admin_pass_label) set_label_if_changed(sa_change_admin_pass_label, get_sa_change_admin_pass_text());
        if (sa_save_default_label) set_label_if_changed(sa_save_default_label, get_sa_save_default_text());
        if (sa_password_label) set_label_if_changed(sa_password_label, get_sa_password_label_text());
        if (sa_repeat_password_label) set_label_if_changed(sa_repeat_password_label, get_sa_repeat_password_text());
        if (sa_hour_label) set_label_if_changed(sa_hour_label, get_sa_hour_text());
        if (sa_date_label) set_label_if_changed(sa_date_label, get_sa_date_text());
        if (sa_save_settings_label) set_label_if_changed(sa_save_settings_label, get_sa_save_settings_text());
        if (objects.change_value_keyboard1) {
            lv_keyboard_set_map(objects.change_value_keyboard1, LV_KEYBOARD_MODE_USER_1, get_chg_keyboard_map(), pass_keyboard_ctrl);
            lv_keyboard_set_mode(objects.change_value_keyboard1, LV_KEYBOARD_MODE_USER_1);
            lv_keyboard_set_textarea(objects.change_value_keyboard1, NULL);
        }
        if (sa_default_confirm_panel && !lv_obj_has_flag(sa_default_confirm_panel, LV_OBJ_FLAG_HIDDEN)) {
            if (sa_default_title_label) set_label_if_changed(sa_default_title_label, get_sa_save_default_text());
            if (sa_default_msg_label) {
                set_label_if_changed(sa_default_msg_label, get_sa_default_confirm_msg());
                lv_obj_set_style_base_dir(sa_default_msg_label, (get_ui_language_index() == 0) ? LV_BASE_DIR_RTL : LV_BASE_DIR_LTR, LV_PART_MAIN | LV_STATE_DEFAULT);
            }
            if (sa_default_ok_label) set_label_if_changed(sa_default_ok_label, get_sg_confirm_text());
            if (sa_default_cancel_label) set_label_if_changed(sa_default_cancel_label, get_sg_cancel_text());
        }
    }
    if (sa_reverse_timer_label) obj_set_pos_if_changed(sa_reverse_timer_label, 117, 39);
    if (sa_change_admin_pass_label) {
        int lidx = get_ui_language_index();
        lv_coord_t y_cap = (lidx == 0) ? 86 : ((lidx == 2) ? 83 : 82);
        obj_set_pos_if_changed(sa_change_admin_pass_label, -4, y_cap);
    }
    if (sa_password_label) {
        int lidx = get_ui_language_index();
        lv_coord_t x_p = (lidx == 0) ? 242 : ((lidx == 2) ? 239 : 218);
        lv_coord_t y_p = (lidx == 0) ? 95 : 99;
        obj_set_pos_if_changed(sa_password_label, x_p, y_p);
    }
    if (sa_repeat_password_label) {
        int lidx = get_ui_language_index();
        lv_coord_t x_rp = (lidx == 0) ? 22 : ((lidx == 2) ? -9 : -7);
        lv_coord_t y_rp = (lidx == 0) ? 96 : 99;
        obj_set_pos_if_changed(sa_repeat_password_label, x_rp, y_rp);
    }
    if (sa_hour_label) obj_set_pos_if_changed(sa_hour_label, 303, 169);
    {
        // پیش‌نویس روز — حتی اگر فلگ «فعال» خاموش باشد صفر اجباری نکن
        // (همان باگ قبلی: بعد از کشیدن، تیک اسلایدر را به ۰ برمی‌گرداند)
        int draft = admin_countdown_draft_days();
        if (draft < 0) draft = 0;
        if (draft > 125) draft = 125;
        const int shown = draft;
        const bool dragging =
            (objects.obj68 && lv_obj_has_state(objects.obj68, LV_STATE_PRESSED));
        if (objects.obj81) {
            char dbuf[16];
            snprintf(dbuf, sizeof(dbuf), "%d", shown);
            set_label_if_changed(objects.obj81, dbuf);
        }
        if (sa_countdown_slider &&
            tick_value_change_obj != sa_countdown_slider &&
            lv_slider_get_value(sa_countdown_slider) != shown) {
            tick_value_change_obj = sa_countdown_slider;
            lv_slider_set_value(sa_countdown_slider, shown, LV_ANIM_OFF);
            tick_value_change_obj = NULL;
        }
        if (objects.obj68 &&
            tick_value_change_obj != objects.obj68 &&
            lv_slider_get_value(objects.obj68) != shown &&
            !dragging) {
            tick_value_change_obj = objects.obj68;
            lv_slider_set_value(objects.obj68, shown, LV_ANIM_OFF);
            tick_value_change_obj = NULL;
        }
    }
    {
        bool new_val = evalBooleanProperty(flowState, 20, 3, "Failed to evaluate Checked state");
        bool cur_val = lv_obj_has_state(objects.obj69, LV_STATE_CHECKED);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.obj69;
            if (new_val) {
                lv_obj_add_state(objects.obj69, LV_STATE_CHECKED);
            } else {
                lv_obj_clear_state(objects.obj69, LV_STATE_CHECKED);
            }
            tick_value_change_obj = NULL;
            if (sa_emergency_mode_label) set_label_if_changed(sa_emergency_mode_label, get_sa_emergency_mode_text());
        }
    }
    {
        bool new_val = evalBooleanProperty(flowState, 22, 3, "Failed to evaluate Checked state");
        bool cur_val = lv_obj_has_state(objects.obj70, LV_STATE_CHECKED);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.obj70;
            if (new_val) {
                lv_obj_add_state(objects.obj70, LV_STATE_CHECKED);
            } else {
                lv_obj_clear_state(objects.obj70, LV_STATE_CHECKED);
            }
            tick_value_change_obj = NULL;
        }
    }
    {
        bool new_val = evalBooleanProperty(flowState, 24, 3, "Failed to evaluate Checked state");
        bool cur_val = lv_obj_has_state(objects.btn_setting_admin_thermocouple_k, LV_STATE_CHECKED);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.btn_setting_admin_thermocouple_k;
            if (new_val) {
                lv_obj_add_state(objects.btn_setting_admin_thermocouple_k, LV_STATE_CHECKED);
            } else {
                lv_obj_clear_state(objects.btn_setting_admin_thermocouple_k, LV_STATE_CHECKED);
            }
            tick_value_change_obj = NULL;
        }
    }
    {
        bool new_val = evalBooleanProperty(flowState, 26, 3, "Failed to evaluate Checked state");
        bool cur_val = lv_obj_has_state(objects.btn_setting_admin_thermocouple_j, LV_STATE_CHECKED);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.btn_setting_admin_thermocouple_j;
            if (new_val) {
                lv_obj_add_state(objects.btn_setting_admin_thermocouple_j, LV_STATE_CHECKED);
            } else {
                lv_obj_clear_state(objects.btn_setting_admin_thermocouple_j, LV_STATE_CHECKED);
            }
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 30, 3, "Failed to evaluate Text in Textarea widget");
        const char *cur_val = lv_textarea_get_text(objects.obj73);
        uint32_t max_length = lv_textarea_get_max_length(objects.obj73);
        if (!textarea_user_active(objects.obj73) && strncmp(new_val, cur_val, max_length) != 0) {
            tick_value_change_obj = objects.obj73;
            lv_textarea_set_text(objects.obj73, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 31, 3, "Failed to evaluate Text in Textarea widget");
        const char *cur_val = lv_textarea_get_text(objects.obj74);
        uint32_t max_length = lv_textarea_get_max_length(objects.obj74);
        if (!textarea_user_active(objects.obj74) && strncmp(new_val, cur_val, max_length) != 0) {
            tick_value_change_obj = objects.obj74;
            lv_textarea_set_text(objects.obj74, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 37, 4, "Failed to evaluate Text in Label widget");
        const char *cur_val = lv_label_get_text(objects.obj78);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj78;
            lv_label_set_text(objects.obj78, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        bool new_val = evalBooleanProperty(flowState, 37, 3, "Failed to evaluate Hidden flag");
        bool cur_val = lv_obj_has_flag(objects.obj78, LV_OBJ_FLAG_HIDDEN);
        if (new_val != cur_val) {
            tick_value_change_obj = objects.obj78;
            if (new_val) {
                lv_obj_add_flag(objects.obj78, LV_OBJ_FLAG_HIDDEN);
            } else {
                lv_obj_clear_flag(objects.obj78, LV_OBJ_FLAG_HIDDEN);
            }
            tick_value_change_obj = NULL;
        }
    }
    if (objects.obj80 && sa_static_due) {
        const char *new_val = get_sa_change_admin_pass_text();
        const char *cur_val = lv_label_get_text(objects.obj80);
        if (strcmp(new_val, cur_val) != 0) {
            tick_value_change_obj = objects.obj80;
            lv_label_set_text(objects.obj80, new_val);
            tick_value_change_obj = NULL;
        }
    }
    {
        const char *new_val = evalTextProperty(flowState, 50, 3, "Failed to evaluate Text in Textarea widget");
        const char *cur_val = lv_textarea_get_text(objects.change_value_admin_pass_1);
        uint32_t max_length = lv_textarea_get_max_length(objects.change_value_admin_pass_1);
        if (!textarea_user_active(objects.change_value_admin_pass_1) && strncmp(new_val, cur_val, max_length) != 0) {
            tick_value_change_obj = objects.change_value_admin_pass_1;
            lv_textarea_set_text(objects.change_value_admin_pass_1, new_val);
            tick_value_change_obj = NULL;
        }
    }
    admin_rtc_refresh_draft(
        admin_dd_editing(admin_time_hour_dropdown),
        admin_dd_editing(admin_time_minute_dropdown),
        admin_dd_editing(admin_date_year_dropdown),
        admin_dd_editing(admin_date_month_dropdown),
        admin_dd_editing(admin_date_day_dropdown));
    admin_sync_rtc_dropdowns_from_vars();
}

void create_screen_screen_admin_password() {
    void *flowState = getFlowState(0, 5);
    (void)flowState;
    lv_obj_t *obj = lv_obj_create(0);
    objects.screen_admin_password = obj;
    lv_obj_set_pos(obj, 0, 0);
    lv_obj_set_size(obj, 480, 320);
    // پس‌زمینهٔ صفحه خاکستری/سرمه‌ای تا خطِ مشکیِ کنارِ پنل دیده نشود
    lv_obj_set_style_bg_color(obj, lv_color_hex(theme_colors[eez_flow_get_selected_theme_index()][4]), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_event_cb(obj, event_handler_cb_screen_admin_password_screen_admin_password, LV_EVENT_ALL, flowState);
    {
        lv_obj_t *parent_obj = obj;
        {
            // Sidebar — matches admin settings sidebar so user can navigate away
            lv_obj_t *obj = lv_obj_create(parent_obj);
            lv_obj_set_pos(obj, 358, 0);
            lv_obj_set_size(obj, 122, 320);
            lv_obj_set_style_pad_all(obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_border_width(obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_radius(obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_add_flag(obj, LV_OBJ_FLAG_FLOATING);
            lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_set_style_bg_color(obj, lv_color_hex(0xff363636), LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_bg_opa(obj, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_shadow_width(obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
            {
                lv_obj_t *parent_obj = obj;
                static const struct { int y; const char *(*txt)(void); const lv_img_dsc_t *icon; bool checked; } sb[] = {
                    { 0,   get_sg_tab_general_text, &img_icon_setting, false },
                    { 65,  get_sg_tab_jack_text,    &img_icon_jack,    false },
                    { 130, get_sg_tab_admin_text,   &img_icon_admin,   true  },
                    { 195, get_sg_tab_help_text,    NULL,              false },
                    { 260, get_sg_tab_exit_text,    &img_icon_exit,    false },
                };
                for (int i = 0; i < 5; i++) {
                    lv_obj_t *btn = lv_btn_create(parent_obj);
                    lv_obj_set_pos(btn, 0, sb[i].y);
                    lv_obj_set_size(btn, 122, 64);
                    // هر دکمه مستقیم به صفحهٔ خودش می‌رود (idx در user_data)
                    lv_obj_set_user_data(btn, (void *)(intptr_t)i);
                    lv_obj_add_event_cb(btn, event_handler_cb_screen_admin_password_sidebar, LV_EVENT_ALL, flowState);
                    add_style_disable_mode_btn(btn);
                    if (i == 4) lv_obj_set_style_bg_color(btn, lv_color_hex(0xffae4c4c), LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_bg_color(btn, lv_color_hex(theme_colors[eez_flow_get_selected_theme_index()][1]), LV_PART_MAIN | LV_STATE_CHECKED);
                    if (sb[i].checked) lv_obj_add_state(btn, LV_STATE_CHECKED);
                    {
                        lv_obj_t *lbl = lv_label_create(btn);
                        lv_obj_set_pos(lbl, -16, 0);
                        lv_obj_set_size(lbl, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
                        lv_obj_set_style_align(lbl, LV_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_text_font(lbl, &ui_font_kalameh_bold_14, LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_text_align(lbl, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_label_set_text(lbl, sb[i].txt());
                        sap_tab_labels[i] = lbl;
                    }
                    if (sb[i].icon) {
                        lv_obj_t *ico = lv_img_create(btn);
                        lv_obj_set_pos(ico, 71, 6);
                        lv_obj_set_size(ico, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
                        lv_img_set_src(ico, sb[i].icon);
                    } else {
                        lv_obj_t *ico = lv_label_create(btn);
                        lv_obj_set_pos(ico, 71, 9);
                        lv_obj_set_size(ico, 32, 32);
                        lv_obj_set_style_text_font(ico, &lv_font_montserrat_28, LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_obj_set_style_text_color(ico, lv_color_white(), LV_PART_MAIN | LV_STATE_DEFAULT);
                        lv_label_set_text(ico, LV_SYMBOL_LIST);
                    }
                }
            }
        }
        {
            // setting_Admin_pass_change_panle_1
            lv_obj_t *obj = lv_obj_create(parent_obj);
            objects.setting_admin_pass_change_panle_1 = obj;
            lv_obj_set_pos(obj, 0, 0);
            lv_obj_set_size(obj, 358, 320);
            lv_obj_clear_flag(obj, LV_OBJ_FLAG_HIDDEN);
            lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
            lv_obj_set_style_bg_color(obj, lv_color_hex(0xff000000), LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_bg_opa(obj, 200, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_border_width(obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
            lv_obj_set_style_radius(obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
            {
                lv_obj_t *parent_obj = obj;
                {
                    lv_obj_t *obj = lv_label_create(parent_obj);
                    objects.obj83 = obj;
                    lv_obj_set_pos(obj, 0, -132);
                    lv_obj_set_size(obj, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
                    lv_obj_set_style_align(obj, LV_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_color(obj, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_font(obj, &ui_font_kalameh_bold, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_align(obj, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_label_set_text(obj, get_admin_pass_prompt_text());
                }
                {
                    // Admin_Pass_prof_keyboard — آیتم ۱۲: تبدیل به کیبرد یونیفرم
                    lv_obj_t *obj = lv_keyboard_create(parent_obj);
                    objects.admin_pass_prof_keyboard = obj;
                    lv_obj_set_pos(obj, -16, 104);
                    lv_obj_set_size(obj, 358, 199);
                    lv_keyboard_set_map(obj, LV_KEYBOARD_MODE_USER_1, get_pass_keyboard_map(), pass_keyboard_ctrl);
                    lv_keyboard_set_mode(obj, LV_KEYBOARD_MODE_USER_1);
                    lv_obj_set_style_text_font(obj, &ui_font_vazirmatn_bold_26, LV_PART_ITEMS | LV_STATE_DEFAULT);
                    lv_obj_add_flag(obj, LV_OBJ_FLAG_SEND_DRAW_TASK_EVENTS);
                    lv_obj_add_event_cb(obj, keyboard_color_draw_task_cb, LV_EVENT_DRAW_TASK_ADDED, NULL);
                    // آیتم ۶: نشانگرِ کلیدِ انتخاب‌شده با کلید MODE روی کیبردِ رمز دیده شود (مثل کیبردِ تغییر مقدارِ مدیر)
                    lv_obj_set_style_bg_color(obj, lv_color_hex(0xff2196f3), LV_PART_ITEMS | LV_STATE_FOCUSED);
                    lv_obj_set_style_bg_opa(obj, LV_OPA_COVER, LV_PART_ITEMS | LV_STATE_FOCUSED);
                    lv_obj_set_style_border_color(obj, lv_color_hex(0xff0d47a1), LV_PART_ITEMS | LV_STATE_FOCUSED);
                    lv_obj_set_style_border_width(obj, 2, LV_PART_ITEMS | LV_STATE_FOCUSED);
                    lv_obj_add_event_cb(obj, event_handler_cb_screen_admin_password_admin_pass_prof_keyboard, LV_EVENT_ALL, flowState);
                    lv_obj_set_style_align(obj, LV_ALIGN_DEFAULT, LV_PART_MAIN | LV_STATE_DEFAULT);
                }
                {
                    // دکمه نمایش/مخفی‌سازی رمز مدیریت (سمت راست کادر رمز)
                    lv_obj_t *eye_btn = lv_btn_create(parent_obj);
                    lv_obj_set_size(eye_btn, 40, 40);
                    lv_obj_set_pos(eye_btn, 132, -81);
                    lv_obj_set_style_align(eye_btn, LV_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_bg_color(eye_btn, lv_color_hex(0xff363636), LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_bg_color(eye_btn, lv_color_hex(0xff4a4a4a), LV_PART_MAIN | LV_STATE_PRESSED);
                    lv_obj_set_style_border_color(eye_btn, lv_color_hex(0xff606060), LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_border_width(eye_btn, 1, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_radius(eye_btn, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_pad_all(eye_btn, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_add_event_cb(eye_btn, eye_toggle_admin_pass_entry, LV_EVENT_CLICKED, NULL);

                    lv_obj_t *eye_lbl = lv_label_create(eye_btn);
                    admin_pass_eye_label = eye_lbl;
                    lv_obj_set_style_align(eye_lbl, LV_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_font(eye_lbl, &lv_font_montserrat_20, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_color(eye_lbl, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_label_set_text(eye_lbl, LV_SYMBOL_EYE_CLOSE);
                }
                {
                    // Admin_Pass_prof_keyboard_place_holder
                    lv_obj_t *obj = lv_textarea_create(parent_obj);
                    objects.admin_pass_prof_keyboard_place_holder = obj;
                    lv_obj_set_pos(obj, 0, -81);
                    lv_obj_set_size(obj, 208, 47);
                    lv_textarea_set_max_length(obj, 128);
                    lv_textarea_set_one_line(obj, true);
                    lv_textarea_set_password_mode(obj, true);
                    lv_obj_clear_flag(obj, LV_OBJ_FLAG_SCROLLABLE);
                    lv_obj_set_style_pad_top(obj, 5, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_pad_bottom(obj, 5, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_font(obj, &lv_font_montserrat_28, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_add_event_cb(obj, event_handler_cb_screen_admin_password_admin_pass_prof_keyboard_place_holder, LV_EVENT_ALL, flowState);
                    lv_obj_set_style_align(obj, LV_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_align(obj, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
                }
            }
        }
    }
    // کیبرد را به textarea وصل نمی‌کنیم تا handler داخلی LVGL دکمه‌های متنی
    // («پاک کردن»/«تایید») را به‌عنوان متن وارد رمز نکند؛ کل ورودی توسط handler سفارشی مدیریت می‌شود.
    lv_keyboard_set_textarea(objects.admin_pass_prof_keyboard, NULL);

    tick_screen_screen_admin_password();
}

void delete_screen_screen_admin_password() {
    lv_obj_del(objects.screen_admin_password);
    objects.screen_admin_password = 0;
    objects.setting_admin_pass_change_panle_1 = 0;
    objects.obj82 = 0;
    objects.obj83 = 0;
    objects.admin_pass_prof_keyboard = 0;
    objects.admin_pass_prof_keyboard_place_holder = 0;
    admin_pass_eye_label = NULL;
    for (int i = 0; i < 5; i++) sap_tab_labels[i] = NULL;
    deletePageFlowState(5);
}

void tick_screen_screen_admin_password() {
    void *flowState = getFlowState(0, 5);
    (void)flowState;
    static int32_t sap_last_lang = -1;
    int32_t sap_lang_now = get_ui_language_index();
    bool sap_lang_changed = (sap_lang_now != sap_last_lang) || g_force_language_refresh;
    bool sap_touch_active = is_ui_interaction_active();
    uint32_t sap_period = sap_touch_active ? 20U : 80U;
    if (!g_force_language_refresh && s_sap_last_tick != 0 && lv_tick_elaps(s_sap_last_tick) < sap_period && !sap_lang_changed) {
        return;
    }
    s_sap_last_tick = lv_tick_get();
    if (sap_lang_changed) {
        sap_last_lang = sap_lang_now;
        const char *(*sap_txt[5])(void) = {
            get_sg_tab_general_text,
            get_sg_tab_jack_text,
            get_sg_tab_admin_text,
            get_sg_tab_help_text,
            get_sg_tab_exit_text
        };
        for (int i = 0; i < 5; i++) {
            if (sap_tab_labels[i]) set_label_if_changed(sap_tab_labels[i], sap_txt[i]());
        }
        if (objects.admin_pass_prof_keyboard) {
            lv_keyboard_set_map(objects.admin_pass_prof_keyboard, LV_KEYBOARD_MODE_USER_1, get_pass_keyboard_map(), pass_keyboard_ctrl);
            lv_keyboard_set_mode(objects.admin_pass_prof_keyboard, LV_KEYBOARD_MODE_USER_1);
            lv_keyboard_set_textarea(objects.admin_pass_prof_keyboard, NULL);
        }
        if (objects.obj83) {
            const char *msg = get_var_wrong_password_atemp();
            if (!msg || !msg[0]) lv_label_set_text(objects.obj83, get_admin_pass_prompt_text());
        }
    }
    {
        if (flowState && objects.admin_pass_prof_keyboard_place_holder && lv_obj_is_valid(objects.admin_pass_prof_keyboard_place_holder)) {
            const char *new_val = evalTextProperty(flowState, 6, 3, "Failed to evaluate Text in Textarea widget");
            const char *cur_val = lv_textarea_get_text(objects.admin_pass_prof_keyboard_place_holder);
            uint32_t max_length = lv_textarea_get_max_length(objects.admin_pass_prof_keyboard_place_holder);
            if (!new_val) new_val = "";
            if (!cur_val) cur_val = "";
            if (!textarea_user_active(objects.admin_pass_prof_keyboard_place_holder) &&
                (max_length == 0 ? strcmp(new_val, cur_val) != 0 : strncmp(new_val, cur_val, max_length) != 0)) {
                tick_value_change_obj = objects.admin_pass_prof_keyboard_place_holder;
                lv_textarea_set_text(objects.admin_pass_prof_keyboard_place_holder, new_val);
                tick_value_change_obj = NULL;
            }
        }
    }
    // نمایش پیام رمز اشتباه / قفل ۱۰ دقیقه‌ای روی label راهنما (obj83)؛ در نبودِ پیام، متن راهنمای پیش‌فرض.
    if (objects.obj83) {
        const char *msg = get_var_wrong_password_atemp();
        const char *want = (msg && msg[0]) ? msg : get_admin_pass_prompt_text();
        const char *cur = lv_label_get_text(objects.obj83);
        if (!cur || strcmp(cur, want) != 0) {
            lv_label_set_text(objects.obj83, want);
        }
    }
}

