                                        { char cbuf[16]; fw_io_code_text(cbuf, sizeof(cbuf), 1, i); lv_label_set_text(fw_q_code_labels[i], cbuf); }
                                        // آیتم: نگه‌داشتنِ ۲ ثانیه → دیالوگِ جابجاییِ پایه (کدِ >=0 یعنی خروجی)
                                        lv_obj_add_event_cb(fw_q_name_labels[i], event_handler_io_remap_press, LV_EVENT_ALL, (void *)(intptr_t)i);
