static void event_handler_link_error_click(lv_event_t *e) {
    link_entry_hide_toast();
}

static void event_handler_link_textarea_click(lv_event_t *e) {
    link_entry_hide_toast();
}

void action_link_check(void) {
    if (!objects.link_entry_textarea || !lv_obj_is_valid(objects.link_entry_textarea)) return;
    const char *raw = lv_textarea_get_text(objects.link_entry_textarea);
    int lang = get_ui_language_index();
    if (!raw || strlen(raw) < 3) {
        const char *t_title = (lang == 2) ? "Link Adresi" : ((lang == 1) ? "Link URL" : "ورود آدرس لینک");
        const char *t_msg = (lang == 2) ? "Lutfen once link adresini girin" : ((lang == 1) ? "Please enter link URL first" : "لطفاً ابتدا آدرس لینک را وارد کنید");
        link_entry_show_toast(LV_SYMBOL_WARNING, t_title, t_msg, 0xfff59e0b, 2500);
        return;
    }
    char url[256];
    while (*raw && isspace((unsigned char)*raw)) raw++;
    if (strncasecmp(raw, "http://", 7) != 0 && strncasecmp(raw, "https://", 8) != 0) {
        snprintf(url, sizeof(url), "http://%s", raw);
    } else {
        strncpy(url, raw, sizeof(url) - 1);
        url[sizeof(url) - 1] = '\0';
    }
    size_t ulen = strlen(url);
    while (ulen > 0 && isspace((unsigned char)url[ulen - 1])) {
        url[--ulen] = '\0';
    }

    const char *t_title = (lang == 2) ? "Sunucu Kontrolu" : ((lang == 1) ? "Server Check" : "بررسی سرور");
    const char *t_msg = (lang == 2) ? "Sunucuda link kontrol ediliyor..." : ((lang == 1) ? "Checking link on server..." : "در حال بررسی لینک در سرور...");
    link_entry_show_toast(LV_SYMBOL_REFRESH, t_title, t_msg, 0xff0284c7, 10000);

    action_link_check_start(url);
}

static void event_handler_link_confirm(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    if (!objects.link_entry_textarea || !lv_obj_is_valid(objects.link_entry_textarea)) return;
    const char *txt = lv_textarea_get_text(objects.link_entry_textarea);
    int lang = get_ui_language_index();
    if (!txt || strlen(txt) < 3) {
        const char *t_title = (lang == 2) ? "Link Adresi" : ((lang == 1) ? "Link URL" : "ورود آدرس لینک");
        const char *t_msg = (lang == 2) ? "Lutfen once link adresini girin" : ((lang == 1) ? "Please enter link URL first" : "لطفاً ابتدا آدرس لینک را وارد کنید");
        link_entry_show_toast(LV_SYMBOL_WARNING, t_title, t_msg, 0xfff59e0b, 2500);
        return;
    }

    char final_url[256];
    complete_and_normalize_url(txt, final_url, sizeof(final_url));
    if (final_url[0] == '\0' || strlen(final_url) < 4) {
        const char *t_title = (lang == 2) ? "Gecersiz Link" : ((lang == 1) ? "Invalid Link" : "آدرس نامعتبر");
        const char *t_msg = (lang == 2) ? "Girilen link adresi gecersiz" : ((lang == 1) ? "Entered link URL is invalid" : "آدرس لینک وارد شده معتبر نیست");
        link_entry_show_toast(LV_SYMBOL_CLOSE, t_title, t_msg, 0xffef4444, 2500);
        return;
    }

    // پیام تایید زمان‌دار زیبا و شروع دانلود
    const char *t_title = (lang == 2) ? "Link Onaylandi" : ((lang == 1) ? "Link Confirmed" : "تایید لینک");
    const char *t_msg = (lang == 2) ? "Sunucuya baglaniliyor ve indiriliyor..." : ((lang == 1) ? "Connecting to server & downloading..." : "لینک تایید شد؛ در حال اتصال و دانلود...");
    link_entry_show_toast(LV_SYMBOL_OK, t_title, t_msg, 0xff10b981, 2000);

    // شروع پروسه دانلود؛ متن کادر تغییر داده نمی‌شود
    start_install_url(final_url);
}

static void event_handler_link_entry_keyboard(lv_event_t *e) {
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_READY) {
        jack_touch_beep();
        action_link_check();
    } else if (code == LV_EVENT_CANCEL) {
        event_handler_link_cancel(e);
    } else if (code == LV_EVENT_VALUE_CHANGED) {
        lv_obj_t *kb = lv_event_get_target(e);
        uint32_t btn_id = lv_buttonmatrix_get_selected_button(kb);
        if (btn_id != LV_BUTTONMATRIX_BUTTON_NONE) {
            const char *txt = lv_buttonmatrix_get_button_text(kb, btn_id);
            if (txt && strcmp(txt, "Space") == 0 && objects.link_entry_textarea) {
                const char *cur = lv_textarea_get_text(objects.link_entry_textarea);
                size_t len = cur ? strlen(cur) : 0;
                if (len >= 5 && strcmp(cur + len - 5, "Space") == 0) {
                    for (int k = 0; k < 5; k++) lv_textarea_delete_char(objects.link_entry_textarea);
                    lv_textarea_add_char(objects.link_entry_textarea, ' ');
                }
            }
        }
    }
}

// منوی مدیر / F5: کلیک دکمه سبز — ایندکس کارت در user_data رویداد (نه target؛ لیبل ممکن است target باشد)
static void framware_install_cb(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    if (get_var_download_panle_state() || installer_scan_busy()) return;
    jack_touch_beep();
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    if (idx < 0 || idx >= FW_INSTALL_CARD_COUNT) {
        // سازگاری با حالت قدیمی: مدل روی خودِ دکمه
        lv_obj_t *t = (lv_obj_t *)lv_event_get_current_target(e);
        const char *model = t ? (const char *)lv_obj_get_user_data(t) : NULL;
        if (model && model[0]) start_install_model(model);
        return;
    }
    // نسخهٔ روی کارت را قفل کن تا نصب به lastfile دوباره وابسته نباشد
    installer_prepare_install(idx);
    const char *model = installer_model(idx);
    if (model && model[0]) start_install_model(model);
}
// × بستن صفحه فریم‌ورها → بازگشت به صفحهٔ قبلی (اطلاعات/بروزرسانی در حالت عادی، منو در F5-بوت)
static void framware_close_cb(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    jack_touch_beep();
    ota_request_cancel();
    set_var_download_panle_state(false);
    bool wasOtaBoot = get_var_ota_enable();
    safe_return_from_ota_to_menu();
    eez_flow_set_screen(wasOtaBoot ? SCREEN_ID_SCREEN_MENU : SCREEN_ID_SCREEN_UPDATE, LV_SCR_LOAD_ANIM_NONE, 0, 0);
}

static void fw_pinmap_close_cb(lv_event_t *e) {
    if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
    if (fw_pinmap_popup) {
        lv_obj_del(fw_pinmap_popup);
        fw_pinmap_popup = NULL;
        fw_pinmap_scroll = NULL;
        fw_pinmap_content = NULL;
        fw_pinmap_popup_idx = -1;
    }
}

