                    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 26);
                    lv_obj_set_style_text_font(title, &ui_font_kalameh_bold_18, LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_obj_set_style_text_color(title, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
                    lv_label_set_text(title, "پیام");
